			'content' => '<p>Une <strong>menace</strong>, c\'est une <em>possibilité</em> qu\'une règle soit enfreinte. Une <strong>vulnérabilité</strong>, c\'est une faiblesse <em>réelle</em> qui rend cette possibilité plausible. Un <strong>modèle de menace</strong>, c\'est la phrase qui relie les deux : « si notre adversaire peut faire X, alors notre règle Y est en danger ».</p><p>Trois questions suffisent à le poser :</p><ul><li><strong>Qu\'est-ce que je protège ?</strong> Une donnée, un service, une réputation. Sans ça, pas de priorité.</li><li><strong>Qui est l\'adversaire ?</strong> Un script kiddie ? Un concurrent ? Un État ? Un employé mécontent ? Le modèle est plus prudent que l\'adversaire réel, sinon on se protège du mauvais côté.</li><li><strong>De quoi est-il capable ?</strong> Lecture du réseau ? Exécution de code chez toi ? Tromper un humain ?</li></ul><p>Et la <strong>politique de sécurité</strong> : la règle que tu veux faire respecter. « Seul le service de facturation lit le dossier client. » Un <strong>mécanisme</strong> est ce qui la fait appliquer : une ACL, un chiffrement, un filtre de requêtes. Un mécanisme ne vaut que si l\'hypothèse du modèle de menace tient : <em>« tant que l\'adversaire respecte les règles du jeu, la politique est respectée »</em>.</p><p><strong>À retenir :</strong> on ne chiffre pas « tout ». On protège ce qui a le plus de valeur, contre ce qui est le plus probable.</p>',
