			'content' => '<p>Un programme C alloue un <em>buffer</em> de 64 octets sur la pile et y copie une chaîne sans vérifier sa longueur. L\'excédent déborde et écrase l\'<strong>adresse de retour</strong> : à la sortie de la fonction, le programme reprend la main <em>où l\'attaquant le décide</em>. Deux conditions suffisent à l\'exploitation : <strong>prendre le contrôle</strong> du compteur de programme, puis <strong>exécuter</strong> ce qu\'on a déposé.</p><p>Les quatre défenses classiques, dans l\'ordre où elles sont apparues :</p><ul><li><strong>Éviter le bug</strong> : écrire du code qui vérifie les tailles. Efficace, mais cela repose sur l\'human : un seul oubli, et c\'est fini.</li><li><strong>Le canari (stack canary)</strong> : une valeur secrète posée entre les variables locales et l\'adresse de retour. Si elle est modifiée, le programme s\'arrête avant de revenir. Elle ne bloque pas l\'écriture, elle détecte la corruption.</li><li><strong>ASLR</strong> : les adresses changent à chaque lancement, donc l\'attaquant ne sait plus où viser. Un canari + ASLR, c\'est déjà très cher à contourner.</li><li><strong>NX (No-eXecute)</strong> : la pile n\'est plus exécutable, on ne peut pas y déposer du code. Il faut alors rebondir sur du code déjà présent : c\'est le <em>ROP</em>, que tu verras chez pwn.college.</li></ul><p><strong>À retenir :</strong> une défense n\'est pas une muraille, c\'est un <em>obstacle</em>. On empile les obstacles ; l\'attaquant cherche le chemin le moins cher, pas le chemin impossible.</p>',
