array(
	'title' => 'Architecture de confiance : séparer les privilèges',
	'excerpt' => 'Comment on découpe un programme pour qu\'un bug n\'ait pas le pouvoir de tout détruire.',
	'content' => 'La leçon 4 de 6.858 : la séparation des privilèges, la notion de « confiance », et le prix à payer.',
	'difficulty' => 'moyen',
	'duration' => 35,
	'xp_bonus' => 45,
	'track' => 'universites',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'single',
		'image' => 'securalabs/univ-01:1.0',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://127.0.0.1:8080',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings' ),
	),
	'video' => array(
		'id' => 'dNl22h1kW1k',
		'title' => '4. Privilege Separation',
		'channel' => 'MIT OpenCourseWare',
		'institution' => 'MIT - 6.858 Computer Systems Security (Fall 2014)',
		'license' => 'CC BY-NC-SA 4.0 - MIT OpenCourseWare',
		'duration' => '1:23:29',
		'note' => 'Cours vidéo de l\'université (MIT OpenCourseWare). Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — séparer les pouvoirs',
			'content' => '<p>Un programme unique qui fait tout (parser une requête, écrire dans la base, envoyer un e-mail) est un programme dont <em>un seul bug</em> donne à l\'attaquant <em>tous les pouvoirs</em>. La <strong>séparation des privilèges</strong> consiste à le découper en deux :</p><ul><li>une partie <strong>sans privilège</strong>, qui fait le travail douteux (parser, calculer) ;</li><li>une partie <strong>privilegiée</strong>, minuscule, qui fait le travail dangereux (écrire dans la base) et qui ne fait <em>que</em> ça, sur des données déjà validées.</li></ul><p>Les deux communiquent par un canal étroit et typé : la partie non privilégiée peut demander « ajoute cette ligne », jamais « exécute cette commande ». Un bug dans le parseur donne alors à l\'attaquant un programme <em>sans</em> privilège, et la partie privilégiée ne retrouve pas le droit de faire n\'importe quoi.</p><p>La <strong>notion de confiance</strong> complète la idée : on dessine une frontière, et on décide « à l\'intérieur de cette frontière, je fais confiance ». Chaque bogue qui renverse une hypothèse de confiance doit être signalé : sinon, la frontière est fausse.</p><p><strong>À retenir :</strong> la sécurité ne vient pas d\'un code parfait, mais d\'un découpage où l\'erreur d\'un composant reste locale. On appelle cela la <em>défense en profondeur</em>.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions sur le découpage et la confiance.</p>',
			'questions' => array(
				array(
					'question' => 'Dans une architecture à privilèges séparés, qui peut écrire dans la base de données ?',
					'mode' => 'choice',
					'choices' => array(
						'La partie non privilégiée, directement',
						'N\'importe quel processus du serveur',
						'Seulement la partie privilégiée, sur demande de la partie non privilégiée',
						'Le client, via une requête SQL directe',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'La séparation consiste justement à réserver le pouvoir à un seul composant.',
					'explanation' => 'Seul le composant privilégié écrit. Le composant non privilégié ne fait que <em>demander</em>, via un canal typé et limité. Le client n\'a jamais accès direct à la base.',
				),
				array(
					'question' => 'Tu trouves un bug dans la partie non privilégiée. Que se passe-t-il si tu n\'as jamais dit à personne que ce composant était de confiance ?',
					'mode' => 'choice',
					'choices' => array(
						'Rien : un bug n\'a d\'importance que s\'il est critique',
						'Le programme se met à jour tout seul',
						'Il faut réécrire le programme en Java',
						'La frontière de confiance est fausse : l\'attaquant a peut-être déjà franchi le périmètre',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'La confiance, c\'est une hypothèse écrite quelque part. Qui l\'a écrite ?',
					'explanation' => 'La confiance doit être <em>explicite</em>. Un composant « de confiance » sans documenter ce qu\'on attend de lui, c\'est une frontière imaginaire : le premier bogue/docs montre qu\'elle n\'existe pas.',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — la politique de séparation',
			'content' => '<p>Le cours 6.858 a laissé dans la salle des cours sa <em>politique de séparation des privilèges</em> (le fichier qui décrit quels processus tournent avec quels droits).</p><p><strong>Mission.</strong> Lis cette politique et relève la <em>valeur du niveau de privilège du processus principal</em> qu\'elle fixe (le niveau de confiance annoncé pour le service web).</p>',
			'questions' => array(
				array(
					'question' => 'Releve le niveau de privilege du processus principal annonce dans la politique de separation des privileges.',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-u03.txt',
					'xp' => 30,
					'hint' => 'La politique est dans <code>/etc/secura-policy</code>. Un <code>ls</code> puis un <code>cat</code> suffisent.',
					'explanation' => 'Une politique de séparation des privilèges dit qui fait quoi et avec quels droits. Savoir lire ce document, c\'est savoir juger si un service est correctement découpé.',
				),
			),
		),
		array(
			'type' => 'exam',
			'format' => 'qcm',
			'title' => 'Task 4 : Examen de fin de room',
			'content' => '<p>Quatre questions chronométrées. 60 % suffisent pour valider.</p>',
			'time_limit' => 300,
			'pass_score' => 60,
			'questions' => array(
				array(
					'question' => 'Quel est l\'objectif principal de la séparation des privilèges ?',
					'mode' => 'choice',
					'choices' => array(
						'Accélérer le programme',
						'Réduire la taille du code',
						'Éviter d\'écrire des tests',
						'Faire qu\'un bug dans une partie reste local et sans pouvoir',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'Pense à ce que l\'attaquant obtient s\'il trouve un bug.',
					'explanation' => 'La séparation des privilèges limite le <em>pouvoir</em> obtenu par un bug. C\'est de la défense en profondeur : même avec un bogue, le système plie sans s\'effondrer.',
				),
				array(
					'question' => 'Un « canal étroit et typé » entre les deux parties, c\'est-à-dire ?',
					'mode' => 'choice',
					'choices' => array(
						'Une interface qui n\'accepte que des messages attendus, pas des commandes libres',
						'Un tunnel chiffré entre les deux processus',
						'Un fichier partagé par les deux processus',
						'Un port réseau réservé à l\'administration',
					),
					'correct' => 0,
					'xp' => 10,
					'hint' => 'Le canal doit interdire ce qui serait dangereux.',
					'explanation' => 'Le canal est <em>typé</em> : la partie non privilégiée peut demander des opérations prévues (« écrire une ligne de log »), pas enchaîner des commandes arbitraires. C\'est ce qui rend la frontière vérifiable.',
				),
				array(
					'question' => 'Quel est le risque principal quand on sépare les privilèges ?',
					'mode' => 'choice',
					'choices' => array(
						'Le programme devient plus lent',
						'La séparation ajoute des points de communication qui peuvent devenir des failles à eux-mêmes',
						'Le code devient plus difficile à lire',
						'Il faut réécrire le programme en Rust',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'Chaque nouvelle frontière est une nouvelle surface.',
					'explanation' => 'Séparer crée une interface : si elle est mal faite (validation absente, courses, messages trop larges), elle devient le maillon faible. Le cours montre ce compromis à chaque cours.',
				),
				array(
					'question' => 'Le serveur web tourne en root et le service de sauvegarde aussi. Quel est le défaut ?',
					'mode' => 'choice',
					'choices' => array(
						'Aucun : tout tourne avec les mêmes droits, c\'est cohérent',
						'La sauvegarde ne peut pas lire les logs',
						'Les deux processus sont dans la même zone de confiance, donc une faille dans l\'un donne le pouvoir de l\'autre',
						'Le service web ne peut pas démarrer',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'Deux processus avec les mêmes droits : quelle est la frontière ?',
					'explanation' => 'Si les deux processus ont les mêmes privilèges, il n\'y a pas de séparation : une faille dans le web donne root. Le cours insiste : la séparation ne sert à rien si les droits sont les mêmes.',
				),
			),
		),
	),
	'i18n' => array(
		'ar' => array(
			'title' => 'بنية الثقة: فصل الامتيازات',
			'excerpt' => 'كيف نقسم برنامجًا حتى لا يمنح خلل واحد سلطة تدمير كل شيء.',
			'tasks' => array(
