array(
	'title' => 'Bac à sable : confiner le code natif',
	'excerpt' => 'Isoler un programme douteux dans un espace fermé : le bac à sable, ses règles, et ce qu\'il ne protège pas.',
	'content' => 'La leçon 7 de 6.858 : le sandboxing du code natif, ou comment faire tourner un programme sans lui faire confiance.',
	'difficulty' => 'moyen',
	'duration' => 35,
	'xp_bonus' => 45,
	'track' => 'universites',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'single',
		'image' => 'securalabs/univ-01:1.0',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://127.0.0.1:8080',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings' ),
	),
	'video' => array(
		'id' => 'I0Psvvky-44',
		'title' => '7. Sandboxing Native Code',
		'channel' => 'MIT OpenCourseWare',
		'institution' => 'MIT - 6.858 Computer Systems Security (Fall 2014)',
		'license' => 'CC BY-NC-SA 4.0 - MIT OpenCourseWare',
		'duration' => '1:23:21',
		'note' => 'Cours vidéo de l\'université (MIT OpenCourseWare). Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — le bac à sable',
			'content' => '<p>Un <strong>bac à sable</strong> (<em>sandbox</em>) est un espace d\'exécution confiné : le programme y tourne, mais ses capacités sont réduites à une liste blanche. C\'est ce qui permet d\'ouvrir un fichier téléchargé, de tester une expression régulière douteuse, ou de faire tourner un plugin sans lui faire confiance.</p><p>Les techniques se combinent :</p><ul><li><strong>Restrictions système</strong> : interdire certains appels système (ouvrir un réseau, exécuter un processus).</li><li><strong>Espaces mémoire séparés</strong> : le programme tourne dans une zone qui ne contient que lui.</li><li><strong>Contrôle des ressources</strong> : temps CPU, mémoire, nombre de fichiers : sinon un programme malveillant s\'installe en mangeant la machine.</li><li><strong>Filtrage des appels</strong> : le bac à sable intercepte les appels et ne laisse passer que ceux autorisés.</li></ul><p>Et la question que pose le cours : <strong>que se passe-t-il si le programme s\'échappe du bac à sable ?</strong> Toute la sécurité repose alors sur la solidité du mécanisme lui-même. D\'où l\'idée de <em>défense en profondeur</em> : un bac à sable, plus une séparation des privilèges, plus un filtrage : si l\'un saute, les autres tiennent.</p><p><strong>À retenir :</strong> un bac à sable ne rend pas le code sûr ; il rend <em>les dégâts</em> bornés. C\'est déjà énorme.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions : ce que le bac à sable borne, et ce qu\'il ne protège pas.</p>',
			'questions' => array(
				array(
					'question' => 'Un bac à sable limite la mémoire, le temps CPU et les appels système. Quel est l\'objectif exact ?',
					'mode' => 'choice',
					'choices' => array(
						'Rendre le programme plus rapide',
						'Remplacer la revue de code',
						'Garantir que le programme est correct',
						'Borner les dégâts si le programme est malveillant ou bogué',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'Le bac à sable ne juge pas le programme : il encadre ses pouvoirs.',
					'explanation' => 'Le bac à sable ne dit pas si le programme est bon ou mauvais : il dit « même s\'il l\'est, voici ce qu\'il peut faire ». La garantie porte sur les dégâts, pas sur la correctness.',
				),
				array(
					'question' => 'Pourquoi le cours insiste-t-il sur la défense en profondeur après la leçon sur le bac à sable ?',
					'mode' => 'choice',
					'choices' => array(
						'Parce qu\'un mécanisme unique peut avoir une faille : les autres mechanisms limitent le dégât',
						'Parce que le bac à sable est trop lent',
						'Parce qu\'il faut deux serveurs web',
						'Parce que le bac à sable ne marche que sous Linux',
					),
					'correct' => 0,
					'xp' => 10,
					'hint' => 'Que se passe-t-il si l\'attaquant s\'échappe du bac à sable ?',
					'explanation' => 'Si l\'évasion est possible, un seul mécanisme ne suffit pas. Empiler des mécanismes indépendants (sandbox + privilèges séparés + filtrage) fait que l\'évasion d\'un ne suffit pas à tout casser.',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — la règle de confinement',
			'content' => '<p>Dans la salle des cours, l\'équipe a laissé le <em>profil de confinement</em> du bac à sable utilisé pour les vérifications automatisées : le fichier qui dit ce que le programme enfermé a le droit de faire.</p><p><strong>Mission.</strong> Lis ce profil et relève la <em>valeur du nombre maximal de processus</em> qu\'il autorise (<code>max_processes</code>). C\'est la preuve que tu as compris ce que borne un bac à sable.</p>',
			'questions' => array(
