					'xp' => 30,
					'hint' => 'Le profil est un fichier de configuration : cherche un .conf ou un .toml dans <code>/etc/secura-policy</code>.',
					'explanation' => 'Borner le nombre de processus, c\'est empêcher un programme de lancer une pluie de sous-processus.',
				),
