array(
	'title' => 'Le web et ses règles : SOP, CSRF et sessions',
	'excerpt' => 'Pourquoi le navigateur mélange parfois les sites, et comment on empêche un site de jouer à ta place.',
	'content' => 'La leçon 9 de 6.858 : le modèle de sécurité du web, la même origine, et les attaques CSRF.',
	'difficulty' => 'moyen',
	'duration' => 35,
	'xp_bonus' => 45,
	'track' => 'universites',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'single',
		'image' => 'securalabs/univ-01:1.0',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://127.0.0.1:8080',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings' ),
	),
	'video' => array(
		'id' => 'WlmKwIe9z1Q',
		'title' => '9. Securing Web Applications',
		'channel' => 'MIT OpenCourseWare',
		'institution' => 'MIT - 6.858 Computer Systems Security (Fall 2014)',
		'license' => 'CC BY-NC-SA 4.0 - MIT OpenCourseWare',
		'duration' => '1:22:08',
		'note' => 'Cours vidéo de l\'université (MIT OpenCourseWare). Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — le modèle de sécurité du web',
			'content' => '<p>Le web repose sur une règle simple et trompeuse : <strong>la même origine</strong>. Un script ne peut lire que les données de son propre site. C\'est ce qui protège le mot de passe qu\'on tape sur une banque, même si la page est truquée.</p><p>Mais l\'interdiction a un versant aveugle : la <strong>policy SOP</strong> empêche une page <em>de lire</em> les réponses d\'un autre site, pas un autre site <em>d\'envoyer</em> une requête avec tes identifiants. C\'est le <strong>CSRF</strong> :</p><ol><li>tu es connecté à ta banque ;</li><li>tu ouvres, dans un autre onglet, une page d\'un site malveillant ;</li><li>cette page envoie automatiquement une requête à la banque : « vire 500 € à mon compte » ;</li><li>la banque voit la requête, elle vient bien de toi (tes identifiants sont joints), elle l\'exécute.</li></ol><p>La parade la plus simple : le <strong>jeton CSRF</strong>. Le serveur place une valeur secrète dans le formulaire ; le navigateur renvoie ce jeton à chaque requête ; le serveur refuse toute requête sans jeton. Un site externe ne peut pas lire ce jeton (règle SOP), donc il ne peut pas le renvoyer.</p><p>Et les autres parades : le mot de passe ne doit pas être stocké en clair, la session doit être protégée par un cookie <code>HttpOnly</code> et <code>Secure</code>, et les requêtes sensibles doivent être vérifiées côté serveur (on ne fait jamais confiance au formulaire).</p><p><strong>À retenir :</strong> le navigateur est un intermédiaire de confiance. Il transmet des jetons à la demande, et il ne vérifie pas qui demande.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions sur le modèle du web et les parades.</p>',
			'questions' => array(
				array(
					'question' => 'La règle de même origine (SOP) empêche une page d\'un site A de lire la réponse du site B. Que ne l\'empêche-t-elle pas ?',
					'mode' => 'choice',
					'choices' => array(
						'D\'empêcher le site B de recevoir une requête envoyée depuis la page A, identifiants compris',
						'D\'empêcher d\'afficher un lien vers le site B',
						'D\'empêcher le site A de charger une image du site B',
						'D\'empêcher le navigateur de garder l\'historique',
					),
					'correct' => 0,
					'xp' => 10,
					'hint' => 'La SOP parle de <em>lire</em> les réponses. Elle dit quelque chose des requêtes ?',
					'explanation' => 'La SOP est une règle de <em>lecture</em>. Le navigateur envoi des requêtes avec les identifiants de session sans demander l\'avis de l\'utilisateur : c\'est l\'angle mort du CSRF.',
				),
				array(
					'question' => 'Pourquoi le jeton CSRF résiste-t-il à l\'attaque ?',
					'mode' => 'choice',
					'choices' => array(
						'Parce qu\'il est chiffré',
						'Parce qu\'une page tierce ne peut pas lire le jeton de la page',
						'Parce qu\'il expire après une seconde',
						'Parce qu\'il est stocké dans un cookie HttpOnly',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'Le site malveillant peut envoyer la requête ; peut-ilFilled le jeton ?',
					'explanation' => 'Le jeton est dans la page du site légitime ; le site malveillant ne peut pas le lire (SOP), donc il ne peut pas le recopier. Il ne peut pas le deviner non plus s\'il est aléatoire.',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — les notes du cours web',
			'content' => '<p>Dans la salle des cours, le cours 6.858 a laissé ses <em>notes sur le web</em> (<code>/srv/cours/mit858/web-notes.txt</code>) : elles récapitulent la politique de même origine, le CSRF et sa parade.</p><p><strong>Mission.</strong> Le bloc de configuration du formulaire est dans le fichier, en trois colonnes : <code>csrf     = TOKEN-…</code>. La valeur du drapeau est ce qui suit le <code>=</code>, tel quel. Trouve-la avec une commande, pas à l\'œil.</p>',
			'questions' => array(
				array(
					'question' => 'Extrais la valeur du champ csrf dans les notes du cours web (web-notes.txt).',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-u05.txt',
					'xp' => 30,
					'hint' => 'La ligne est indentée : <code>grep "^ *csrf" /srv/cours/mit858/web-notes.txt</code> la trouve, puis <code>cut -d" " -f5</code> isole la valeur. Plus court : <code>awk \'/^ *csrf *=/{print $3}\' /srv/cours/mit858/web-notes.txt</code>.',
					'explanation' => 'Un jeton anti-CSRF est une valeur aléatoire liée à la session : le formulaire légitime la connaît, un site tiers ne peut pas la deviner. Le lire dans un fichier de configuration, c\'est comprendre où le serveur la range et comment un attaquant pourrait la voler.',
				),
			),
		),
		array(
			'type' => 'exam',
			'format' => 'qcm',
			'title' => 'Task 4 : Examen de fin de room',
			'content' => '<p>Quatre questions chronométrées. 60 % suffisent pour valider.</p>',
			'time_limit' => 300,
			'pass_score' => 60,
			'questions' => array(
				array(
					'question' => 'Une banque utilise un cookie de session sans l\'attribut HttpOnly. Quel risque ?',
					'mode' => 'choice',
					'choices' => array(
						'Aucun risque, le cookie reste privé',
						'Un script injecté dans une page peut lire le cookie de session',
						'Le cookie devient plus gros',
						'La session ne peut plus être fermée',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'HttpOnly : à qui le cookie est-il visible ?',
					'explanation' => 'HttpOnly empêche JavaScript de lire le cookie : une injection de script ne peut pas voler la session. Secure force HTTPS. Les deux vont ensemble.',
				),
				array(
					'question' => 'Quel est le rôle du cookie <code>SameSite</code> ?',
					'mode' => 'choice',
					'choices' => array(
						'Chiffrer le cookie',
						'Allonger la durée de vie du cookie',
						'Dire au navigateur de ne pas envoyer le cookie lors d\'une requête venue d\'un autre site',
						'Signer le cookie',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'SameSite = « même site ». Que se passe-t-il quand ce n\'est pas le cas ?',
					'explanation' => 'SameSite=Lax ou Strict fait que le cookie de session n\'accompagne pas une requête cross-site : c\'est une parade <em>supplémentaire</em> contre le CSRF, en plus du jeton.',
				),
				array(
					'question' => 'Le serveur vérifie l\'identifiant de l\'utilisateur envoyé par le formulaire, mais ne vérifie pas l\'origine de la requête. Quel est le risque ?',
					'mode' => 'choice',
					'choices' => array(
						'Aucun : le serveur fait ce qu\'on lui demande',
						'Le serveur perdra ses données',
						'Le mot de passe de l\'utilisateur sera envoyé en clair',
						'Une requête forgée depuis un autre site peut se faire passer pour l\'utilisateur connecté',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'La requête est-elle prouvée comme venant de l\'utilisateur ?',
					'explanation' => 'Sans vérification d\'origine (jeton CSRF, en-tête Origin, SameSite), une requête forgée est indistinguishable d\'une vraie requête pour le serveur : c\'est la définition du CSRF.',
				),
				array(
					'question' => 'Dans la défense en profondeur, que vient apporter le hachage du mot de passe si on a déjà un jeton CSRF ?',
					'mode' => 'choice',
					'choices' => array(
						'Un autre remède : même si la base est volée, les mots de passe ne sont pas directement utilisables',
						'Rien : les deux protègent la même chose',
						'Le mot de passe devient plus court',
						'La connexion devient plus rapide',
					),
					'correct' => 0,
					'xp' => 10,
					'hint' => 'Les deux mécanismes protègent des choses différentes.',
					'explanation' => 'Le jeton CSRF protège l\'identité <em>pendant</em> la session ; le hachage protège les mots de passe <em>après</em> un vol de base. Chaque couche traite une menace différente.',
				),
			),
		),
	),
	'i18n' => array(
