array(
	'title' => 'Segmenter, isoler, pivoter : la sécurité réseau',
	'excerpt' => 'Le réseau ne protège pas tout seul : sans segmentation, une porte ouverte donne tout le bâtiment.',
	'content' => 'La leçon 12 de 6.858 : ce que le réseau TCP/IP garantit, ce qu\'il ne garantit pas, et le rôle de la segmentation.',
	'difficulty' => 'moyen',
	'duration' => 35,
	'xp_bonus' => 45,
	'track' => 'universites',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'single',
		'image' => 'securalabs/univ-01:1.0',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://127.0.0.1:8080',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings' ),
	),
	'video' => array(
		'id' => 'BZTWXl9QNK8',
		'title' => '12. Network Security',
		'channel' => 'MIT OpenCourseWare',
		'institution' => 'MIT - 6.858 Computer Systems Security (Fall 2014)',
		'license' => 'CC BY-NC-SA 4.0 - MIT OpenCourseWare',
		'duration' => '1:18:26',
		'note' => 'Cours vidéo de l\'université (MIT OpenCourseWare). Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — segmentation et pivot',
			'content' => '<p>Le réseau repose sur TCP/IP, un protocole qui a été conçu pour <em>transporter</em>, pas pour <em>protéger</em>. Trois exemples de ce qu\'il ne fait pas :</p><ul><li><strong>Les numéros de séquence</strong> sont courts (32 bits) : on peut les deviner et injecter des données dans une connexion.</li><li><strong>L\'adresse IP</strong> se spoof facilement : rien ne vérifie que la machine qui envoie est bien celle qu\'elle dit être.</li><li><strong>Le chiffrement de base</strong> n\'existe pas dans TCP/IP : tout passe en clair sur le câble.</li></ul><p>La parade de base est <strong>la segmentation</strong> : découper le réseau en zones, et placer des pare-feu <em>entre</em> les zones. Le but n\'est pas d\'empêcher l\'attaque, mais d\'empêcher qu\'elle se propage : un serveur web compromis dans la zone « public » ne doit pas pouvoir joindre la base de données dans la zone « données ».</p><p>Et si l\'attaquant est <em>déjà</em> dans le réseau ? C\'est le <strong>pivot</strong> : utiliser une machine compromise comme relais pour atteindre une zone qu\'on ne voit pas. Un vrai pare-feu qui bloque un trafic venant de l\'intérieur est donc indispensable : la zone publique ne parle jamais directement à la zone interne.</p><p><strong>À retenir :</strong> la sécurité réseau ne se joue pas sur le câble, mais sur le <em>plan</em> : qui parle à qui, et avec quelle justification.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions sur ce que le réseau fait, et ce qu\'il ne fait pas.</p>',
			'questions' => array(
				array(
					'question' => 'Une machine du réseau public peut envoyer une requête directly au serveur de base de données. Quel est le défaut ?',
					'mode' => 'choice',
					'choices' => array(
						'La segmentation est incomplete : la zone publique ne devrait pas joindre la zone des données',
						'Aucun : c\'est normal, le réseau public est fait pour ça',
						'Le serveur de base de données est trop lent',
						'Le protocole TCP/IP est trop ancien',
					),
					'correct' => 0,
					'xp' => 10,
					'hint' => 'À quoi sert un pare-feu, s\'il est entre deux zones qui se parlent librement ?',
					'explanation' => 'Si le public joint directement les données, il n\'y a plus de séparation : la moindre faille sur le web donne accès aux données. La segmentation existe pour que ce chemin n\'existe pas.',
				),
				array(
					'question' => 'Pourquoi le chiffrement des protocoles modernes est-il fait « au-dessus » de TCP/IP plutôt que « dans » TCP/IP ?',
					'mode' => 'choice',
					'choices' => array(
						'Parce que c\'est plus rapide',
						'Parce que la sécurité doit venir de l\'application (TLS) et non d\'un transport qui ne connaît pas le contexte',
						'Parce que TCP/IP est interdit en Europe',
						'Parce que le routeur ne sait pas chiffrer',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'Le transport ignore ce qu\'il transporte : il ne peut pas savoir ce qui est secret.',
					'explanation' => 'Le transport déplace des octets, sans savoir ce qu\'ils signifient. La confidentialité doit donc être apportée par l\'application (TLS) ou par un tunnel (VPN), qui connaissent le sens des données.',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — le plan de segmentation',
			'content' => '<p>Dans la salle des cours, le <em>plan de segmentation</em> du réseau du laboratoire décrit les zones et ce que chacune contient. Le fichier <code>/srv/cours/mit857/segmentation-plan.txt</code> liste les services de la zone la plus restreinte, un par ligne, sous la forme <code>service:port</code>.</p><p><strong>Mission.</strong> Le drapeau de cette room est le <em>premier service dans l\'ordre alphabétique</em> : c\'est celui qui démarre en premier, et donc celui qu\'on vérifie en premier.</p>',
			'questions' => array(
				array(
					'question' => 'Quel est le premier service (ordre alphabetique) de la zone des donnees sensibles ?',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-u06.txt',
					'xp' => 30,
					'hint' => 'Coupe le port, trie, prends le premier : <code>cut -d: -f1 /srv/cours/mit857/segmentation-plan.txt | sort | head -1</code>.',
					'explanation' => 'Trier puis prendre le premier, c\'est une opération qu\'on refait sans arrêt en administration : lister les services, les ordonner, vérifier celui qui démarre avant les autres. Un service de sauvegarde qui démarre avant son volume ne sauvegarde rien.',
				),
			),
		),
		array(
			'type' => 'exam',
			'format' => 'qcm',
			'title' => 'Task 4 : Examen de fin de room',
			'content' => '<p>Quatre questions chronométrées. 60 % suffisent pour valider.</p>',
			'time_limit' => 300,
			'pass_score' => 60,
			'questions' => array(
				array(
					'question' => 'Quel est le rôle principal de la segmentation réseau ?',
					'mode' => 'choice',
					'choices' => array(
						'Accélérer les échanges entre zones',
						'Limiter la propagation d\'une compromission d\'une zone à l\'autre',
						'Réduire le nombre de serveurs',
						'Rendre le pare-feu inutile',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'Pense au rôle du pare-feu « entre » les zones.',
					'explanation' => 'La segmentation ne vise pas à interdire tout, mais à <em>cloisonner</em> : une compromission doit rester dans sa zone. C\'est la différence entre un réseau plat et un réseau maîtrisé.',
				),
				array(
					'question' => 'Une machine compromise dans la zone « public » arrive à joindre la zone « interne ». Que faut-il en premier ?',
					'mode' => 'choice',
					'choices' => array(
						'Changer tous les mots de passe',
						'Éteindre le serveur web',
						'Rechercher où le chemin a étéPossible : règle de pare-feu, route, ou service exposé',
						'Installer un antivirus sur la machine compromise',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'Un chemin possible est un chemin à refermer.',
					'explanation' => 'On cherche d\'où vient le passage : une règle trop large, un tunnel, un service qui écoute. Réparer la cause (le chemin) plutôt que traiter les symptômes (la machine compromise).',
				),
				array(
					'question' => 'Pourquoi un pare-feu bloque-t-il rarement le trafic venant de l\'intérieur ?',
					'mode' => 'choice',
					'choices' => array(
						'Parce qu\'il ne sait pas faire',
						'Parce que le routeur bloque en amont',
						'Parce que le pare-feu ne voit que le trafic entrant',
						'Parce que le trafic sortant est considéré comme légitime : c\'est l\'administration qu\'il faut limiter',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'Le pare-feu filtre le trafic qu\'il voit. Le trafic sortant est-il filtrable ?',
					'explanation' => 'Un pare-feu stateful voit le trafic dans les deux sens, mais il laisse sortir ce qui est « demandé ». La vraie parade au pivot est la segmentation + le contrôle des flux sortants.',
				),
				array(
					'question' => 'Un VPN relie deux sites distants. Quel risque nouveau introduit-il ?',
					'mode' => 'choice',
					'choices' => array(
						'Il crée un chemin entre les deux réseaux : une compromission peut se propager d\'un site à l\'autre',
						'Aucun : il chiffre tout',
						'Il ralentit forcément toutes les communications',
						'Il remplace la necessity d\'un pare-feu',
					),
					'correct' => 0,
					'xp' => 10,
					'hint' => 'Un VPN relie deux zones. Qu\'est-ce qu\'il y a sur le pont ?',
					'explanation' => 'Un VPN est un tunnel : il rend joignables deux zones qui ne l\'étaient pas. Il faut donc appliquer entre elles les mêmes règles qu\'à l\'intérieur de chaque zone.',
				),
			),
		),
	),
	'i18n' => array(
