	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — ce que TLS garantit (et ce qu\'il ne garantit pas)',
			'content' => '<p>Quand tu te connectes en HTTPS, trois choses se jouent :</p><ol><li><strong>Le canal</strong> : le client et le serveur négocient un algorithme de chiffrement et une clé de session. Tout ce qui suit passe chiffré, et personne au milieu ne peut lire ni modifier.</li><li><strong>L\'identité</strong> : le serveur présente un <strong>certificat</strong>, qui dit « je suis bien intranet.lab ». Le client le vérifie : signature de l\'autorité, date de validité, nom attendu.</li><li><strong>La fraîcheur</strong> : un numéro unique par session évite qu\'on rejoue un ancien message.</li></ol><p>Le point dur, dans le cours, c\'est la <strong>chaîne de confiance</strong>. Le certificat n\'est pas signé par lui-même : il est signé par une autorité, qui est elle-même signée par une autre, jusqu\'à une racineoid <em>déjà</em> dans le navigateur. Si la racine est compromise, tout s\'effondre : c\'est le sujet des « autorites de certification » et de leurs incidents.</p><p>Et les limites à retenir :</p><ul><li>HTTPS ne dit rien sur ce que le site <em>fait</em> de tes données une fois reçues.</li><li>Un certificat valide ne dit pas que le site est honnête : il dit que quelqu\'un a payé pour ce nom.</li><li>Le cadenas du navigateur garantit le chiffrement et l\'identité <em>technique</em>, pas la réputation.</li></ul><p><strong>À retenir :</strong> TLS protège le <em>tuyau</em>. Ce qui se passe à l\'autre bout du tuyau est l\'affaire de l\'application.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions sur ce que le cadenas garantit vraiment.</p>',
			'questions' => array(
