					'correct' => 2,
					'xp' => 10,
					'hint' => 'La racine est déjà dans le navigateur : elle est donc acceptée sans discussion.',
					'explanation' => 'Toute la chaîne repose sur la racine. Si une autorité intermediate est compromise, elle peut obtenir des certificats valides pour des noms qu\'elle ne contrôle pas, et tous les navigateurs les accepteront.',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — l\'audit du certificat',
			'content' => '<p>Dans la salle des cours, un <em>audit TLS</em> a été laissé dans <code>/srv/cours/mit857/tls-audit.txt</code> : le certificat du service y est décrit ligne à ligne.</p><p><strong>Mission.</strong> La valeur du drapeau est la version de TLS annoncée par le service, telle qu\'elle est écrite (le champ <code>tls</code>).</p>',
			'questions' => array(
				array(
					'question' => 'Quelle version de TLS le service annonce-t-il dans l\'audit (champ tls) ?',
					'mode' => 'flag',
