					'explanation' => 'Lire la version TLS annoncée par un service, c\'est le premier réflexe d\'un audit : TLS 1.0 et 1.1 sont retirés, 1.2 reste acceptable, 1.3 est l\'état de l\'art. On ne devine pas, on lit ce que le service dit de lui-même, puis on le vérifie.',
				),
