		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings' ),
	),
	'video' => array(
		'id' => 'MT7X17ZRo1U',
		'title' => '17. User Authentication',
		'channel' => 'MIT OpenCourseWare',
		'institution' => 'MIT - 6.858 Computer Systems Security (Fall 2014)',
		'license' => 'CC BY-NC-SA 4.0 - MIT OpenCourseWare',
		'duration' => '1:19:48',
		'note' => 'Cours vidéo de l\'université (MIT OpenCourseWare). Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — prouver qui on est',
			'content' => '<p>Un système d\'authentification répond à trois questions :</p><ul><li><strong>Que prouvez-vous ?</strong> Quelque chose que vous <em>savez</em> (mot de passe), que vous <em>avez</em> (carte, clé), ou que vous <em>êtes</em> (empreinte, visage).</li><li><strong>À qui le prouvez-vous ?</strong> Le serveur, à travers un canal protégé ; sinon, votre mot de passe voyage en clair et peut être rejoué.</li><li><strong>Et ensuite ?</strong> Le serveur crée une <strong>session</strong> : un identifiant aléatoire, difficulté à deviner, associé à un cookie protégé.</li></ul><p>La faiblesse historique est le mot de passe : court, réutilisé, transmis ou stocké mal. Les parades : <strong>longueur</strong> (une phrase de quatre mots bat un mot complicated), <strong>hachage avec sel</strong> (le sel est stocké à côté, il empêche que deux mots de passe identiques donnent le même résultat), et <strong>second facteur</strong> (un code à usage unique sur ton téléphone).</p><p>Et surtout : la <strong>déconnexion</strong> et la <strong>session</strong>. Un cookie de session mal protégé (pas de HttpOnly, pas d\'expiration, jamais révoqué) est aussi grave qu\'un mot de passe faible : il ne se vole pas, il se copie.</p><p><strong>À retenir :</strong> on n\'authentifie pas un mot de passe, on authentifie une <em>session</em>. Tout ce qui weakens la session (cookie non protégé, pas d\'expiration, pas de révocation) est un défaut d\'authentification.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions : le bon réflexe, et le maillon faible oublié.</p>',
			'questions' => array(
				array(
					'question' => 'Quel est le meilleur mot de passe selon les recommandations du cours ?',
					'mode' => 'choice',
					'choices' => array(
						'Un mot complicated avec des chiffres et des symboles',
						'Le même que partout, avec une majuscule ajoutée',
						'Une phrase de plusieurs mots, longue et sans date ni nom personnel',
						'Un mot tiré du dictionnaire, avec un chiffre à la fin',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'Ce qui compte, c\'est la longueur et l\'imprévisibilité, pas la « complexité ».',
					'explanation' => 'Les recommendations actuelles privilégient la longueur : « chat bleu vraiment rapide » est plus fort et plus facile à retenir qu\'un « P@ssw0rd! ».',
				),
				array(
					'question' => 'Le site propose « se souvenir de moi » avec un jeton qui ne expire jamais et n\'est pas révocable. Quel est le problème ?',
					'mode' => 'choice',
					'choices' => array(
						'Aucun, c\'est pratique',
						'Le jeton est trop court',
						'Le navigateur refusera de le stocker',
						'Un jeton volé reste utilisable indéfiniment : la session ne peut plus être retirée',
