					'correct' => 3,
					'xp' => 10,
					'hint' => 'Pense à ce que tu fais quand tu crois qu\'un compte a été volé.',
					'explanation' => 'La révocabilité est ce qui permet de couper l\'accès. Sans elle, « se déconnecter de tous les appareils » est impossible, et un jeton volé est un accès permanent.',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — la politique d\'authentification',
			'content' => '<p>Dans la salle des cours, la <em>politique d\'authentification</em> du service fixe les règles : longueur minimale, tentatives, second facteur. Elle s\'applique à tous les comptes, et l\'inventaire des comptes est dans <code>/srv/cours/mit857/comptes.csv</code>.</p><p><strong>Mission.</strong> La politique ne dit pas combien de comptes elle protège : il faut compter. La valeur du drapeau est le <em>nombre de lignes du fichier de comptes, moins la ligne d\'en-tête</em>.</p>',
			'questions' => array(
				array(
					'question' => 'Combien de comptes la politique d\'authentification protege-t-elle (lignes de comptes.csv moins l\'en-tete) ?',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-u08.txt',
					'xp' => 30,
					'hint' => '<code>tail -n +2 /srv/cours/mit857/comptes.csv | wc -l</code> : « tail -n +2 » saute l\'en-tête, « wc -l » compte ce qui reste.',
					'explanation' => 'Une politique qui s\'applique à « tous les comptes » sans qu\'on sache combien ils sont n\'est pas applicable : on ne peut pas vérifier un périmètre qu\'on n\'a pas compté. Compter les lignes d\'un inventaire est le geste de base de tout audit.',
				),
			),
		),
		array(
			'type' => 'exam',
