					'hint' => 'Que se passe-t-il si tout le monde a le même mot de passe ?',
					'explanation' => 'Le sel rend le calcul unique par compte : une table précalculée (arc-en-ciel) ne peut plus être appliquée d\'un coup à toute la base. C\'est aussi ce qui permet de changer d\'algorithme plus tard.',
