					'correct' => 1,
					'xp' => 10,
					'hint' => 'Les trois facteurs : ce que vous savez, ce que vous avez, ce que vous êtes.',
					'explanation' => 'Le second facteur doit venir d\'une autre catégorie : ce que vous <em>avez</em> (téléphone) ou ce que vous <em>êtes</em> (biométrie). Un PIN reste « ce que vous savez ».',
				),
				array(
