			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — les trois briques',
			'content' => '<p>Ron Rivest commence par une question simple : <strong>à qui fais-tu confiance ?</strong> Toute la cryptographie moderne découle de cette réponse.</p><ol><li><strong>Le chiffrement symétrique</strong> (une clé pour chiffrer et déchiffrer : AES). Rapide, solide, mais les deux parties doivent partager la clé : comment l\'échanger sans laonyaoyer ? C\'est le problème de la distribution des clés.</li><li><strong>Le chiffrement asymétrique</strong> (deux clés liées : une publique, une privée : RSA, courbes elliptiques). La clé publique peut circuler à la main, sur un canal non sécurisé : c\'est elle qui résout le problème de la distribution. Plus lent, donc réservé aux clés et aux signatures.</li><li><strong>La signature numérique</strong> : on signe avec sa clé privée, on vérifie avec la clé publique. Elle prouve <em>l\'origine</em> et <em>l\'intégrité</em> du message — pas sa secret.</li></ol><p>Et le <strong>hachage</strong> : une empreinte courte et à sens unique. Elle vérifie qu\'un fichier n\'a pas changé (c\'est l\'empreinte numérique du cours), et sert de base aux mots de passe (avec sel) et aux signatures.</p><p><strong>À retenir :</strong> le chiffrement cache, la signature prouve. Confondre les deux, c\'est la erreur classique de l\'exercice.</p>',
			'questions' => array(),
		),
