	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — registres, pile, adresses',
			'content' => '<p>Un programme qui s\'exécute, c\'est trois choses qui bougent en permanence : des <strong>données</strong>, des <strong>adresses</strong>, et un <strong>compteur de programme</strong> qui dit « execute cette instruction ». En x86-64, les données vivent d\'abord dans des <strong>registres</strong> (des cases ultra rapides : <code>rax</code>, <code>rdi</code>, <code>rsp</code>, <code>rbp</code>...), puis en <strong>mémoire</strong>, qui est découpée en zones.</p><p>La zone qui nous intéresse est la <strong>pile</strong> (<em>stack</em>). À chaque appel de fonction, la pile <em>grandit</em> vers le bas : on y pose les variables locales, puis l\'adresse de retour. Schéma mental du haut vers le bas :</p><ul><li>variables locales (le buffer que l\'on va remplir) ;</li><li>le <strong>canari</strong> (une valeur sentinelle) ;</li><li>l\'<strong>adresse de retour</strong> (l\'endroit où le CPU doit reprendre après la fonction) ;</li><li>la <strong>pointeur de pile</strong> (<code>rsp</code>), qui dit où s\'arrête la pile.</li></ul><p>Deux idées à retenir :</p><ul><li><strong>Un dépassement déborde vers le haut</strong> : vers l\'adresse de retour. C\'est exactement ce qu\'on cherche à atteindre.</li><li><strong>Les adresses sont des nombres</strong> : si je connais l\'adresse d\'une instruction, je peux y sauter. C\'est le point de départ du ROP, qu\'on verra dans deux rooms.</li></ul><p><strong>À retenir :</strong> comprendre la pile, c\'etit comprendre <em>où</em> un programme place ses données — et donc où un attaquant peut agir.</p>',
			'questions' => array(),
