array(
	'title' => 'Déborder la pile : le canari et l\'offset',
	'excerpt' => 'Comment on mesure un offset, et pourquoi le canari ne sert à rien si on ne sait pas où il est.',
	'content' => 'La vidéo « Smashing the Stack » de pwn.college : le mécanisme du débordement et la mesure de l\'offset.',
	'difficulty' => 'moyen',
	'duration' => 35,
	'xp_bonus' => 45,
	'track' => 'universites',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'single',
		'image' => 'securalabs/univ-01:1.0',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://127.0.0.1:8080',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings' ),
	),
	'video' => array(
		'id' => 'PVx1hUlMxtQ',
		'title' => 'pwn.college - Memory Errors - Smashing the Stack',
		'channel' => 'pwn.college',
		'institution' => 'pwn.college (Arizona State University)',
		'license' => 'Reutilisation non commerciale autorisee, avec attribution (pwn.college)',
		'duration' => '16:35',
		'note' => 'Vidéo de l\'université (pwn.college). Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — mesurer l\'offset',
			'content' => '<p>Le canari est un obstacle, pas un mur : on peut l\'écraser. Mais il faut pour cela connaître <strong>exactement</strong> combien d\'octets séparent le début du buffer et le canari. Cet <strong>offset</strong> se mesure, et c\'est tout le travail du TP.</p><p>La méthode classique, en trois temps :</p><ol><li>Écris une longue suite de caractères reconnaissables (<code>AAAAAAAA...AAAA</code>) pour dépasser le buffer et écraser le canari et l\'adresse de retour.</li><li>Le programme plante (SIGSEGV ou « stack smashing detected ») : laPositions du plantage te dit à peu près où tu es arrivé.</li><li>Affine en changeant la taille et le motif (souvent <code>A</code>, puis <code>B</code>, puis <code>C</code>…) pour localiser <em>exactement</em> l\'octet qui casse quelque chose.</li></ol><p>Une fois l\'offset connu, l\'attaque devient précise : on remplit le buffer, on réécrit le canari avec sa valeur d\'origine (si on la connaît), puis on place l\'adresse voulue à la place de l\'adresse de retour.</p><p>Et le contre-mesure : <strong>ASLR</strong> (les adresses changent), <strong>NX</strong> (la pile n\'est pas exécutable) et le canari. Le cours montre que combiner ces trois protections rend l\'exploitation directe très coûteuse : il faut alors passer par le ROP (room suivante).</p><p><strong>À retenir :</strong> l\'offset n\'est pas une astuce, c\'est une mesure. On ne « devine » pas : on mesure, on recommence, on affine.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions sur la mesure et les protections.</p>',
			'questions' => array(
