						'Pour obtenir un meilleur score au TP',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'Le motif sert de règle graduée.',
					'explanation' => 'Un motif de octets distincts (AAAA BBBB CCCC) sert de règle : quand le programme casse, on sait exactement où on en est, donc combien d\'octets il faut avant l\'adresse de retour.',
				),
				array(
					'question' => 'ASLR rend l\'adresse de retour imprévisible. Comment le cours propose-t-il de faire face ?',
