					'xp' => 10,
					'hint' => 'On ne devine pas une adresse aléatoire : on la récupère.',
					'explanation' => 'ASLR impose de <em>révéler</em> l\'adresse (fuite d\'information : adresse affichée dans une page, pointeur dans un crash, etc.). À défaut, l\'exploitation devient une question de probabilités.',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — le canari',
			'content' => '<p>Dans <code>/home/ctf/pwn</code>, les notes du TP « Smashing the stack » ont été laissées : elles décrivent le programme vulnérable et la façon de mesurer l\'offset.</p><p><strong>Mission.</strong> Lis ces notes et relève la <em>valeur du canari</em> utilisée par le programme vulnérable du TP (champ <code>canary_value</code>).</p>',
