array(
	'title' => 'ROP : construire une attaque sans shellcode',
	'excerpt' => 'Quand la pile ne peut plus exécuter, on fait rebondir le programme sur lui-même.',
	'content' => 'L\'introduction au Return-Oriented Programming de pwn.college : le principe des gadgets et des chaînes de retour.',
	'difficulty' => 'difficile',
	'duration' => 40,
	'xp_bonus' => 55,
	'track' => 'universites',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'single',
		'image' => 'securalabs/univ-01:1.0',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://127.0.0.1:8080',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings' ),
	),
	'video' => array(
		'id' => 'El8-vMDJ1zY',
		'title' => 'pwn.college - Return Oriented Programming - Introduction',
		'channel' => 'pwn.college',
		'institution' => 'pwn.college (Arizona State University)',
		'license' => 'Reutilisation non commerciale autorisee, avec attribution (pwn.college)',
		'duration' => '8:54',
		'note' => 'Vidéo de l\'université (pwn.college). Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — le retour comme instruction',
			'content' => '<p>Avec NX, la pile est une zone de <em>données</em> : on ne peut plus y déposer de code à exécuter. Mais on peut toujours <strong>choisir l\'endroit où le programme reprend</strong>. C\'est tout le principe du ROP.</p><p>L\'idée est simple et startling : un programme déjà compilé contient des morceaux de code utiles qui se terminent par <code>ret</code>. Ce sont des <strong>gadgets</strong>. Si l\'adresse de retour pointe sur un gadget qui pose un registre, puis sur un autre gadget qui enchaîne, le programme enchaîne des actions <em>sans exécuter une seule de nos instructions</em>.</p><p>Exemple de raisonnement :</p><ol><li>Il faut que <code>rdi</code> contienne l\'adresse de la commande <code>"/bin/sh"</code>.</li><li>Il faut ensuite appeler <code>execve</code>.</li><li>Un gadget <code>pop rdi ; ret</code> permet de placer une valeur dans <code>rdi</code>.</li><li>On empile : <code>pop rdi</code>, puis l\'adresse de la chaîne, puis l\'adresse de <code>execve</code>.</li></ol><p>Chaque gadget se termine par <code>ret</code> : le « retour » devient l\'instruction qui enchaîne la chaîne. C\'est élégant, et c\'est exactement l\'idée du cours : on ne crée pas de code, on <em>réutilise</em> celui qui existe, comme on répare un moteur avec des pièces d\'un autre moteur.</p><p>Et le bricolage toujours recommencé : c\'est le <strong>« binary lego »</strong>. Les outils (<code>ROPgadget</code>, <code>pwntools</code>) servent à trouver les gadgets et à bâtir la chaîne automatiquement.</p><p><strong>À retenir :</strong> le ROP montre que « pas de code injectable » ne veut pas dire « pas d\'exploitation ». Il déplace la difficulté, il ne la supprime pas.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions sur le principe du ROP.</p>',
			'questions' => array(
				array(
					'question' => 'Qu\'est-ce qu\'un « gadget » en ROP ?',
					'mode' => 'choice',
					'choices' => array(
						'Un bout de code ajouté au programme par l\'attaquant',
						'Un outil qui trouve les vulnérabilités',
						'Un bout de code déjà présent dans le binaire, qui se termine par <code>ret</code>',
						'Une fonction de la libc',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'Avec NX, on ne peut pas déposer de code : qu\'est-ce qu\'on utilise à la place ?',
					'explanation' => 'Un gadget, c\'est une séquence d\'instructions déjà compilées qui se termine par un <code>ret</code>. On ne crée rien : on recycle. C\'est ce qui rend la technique si portable.',
				),
				array(
					'question' => 'Pourquoi la protection NX (pile non exécutable) ne bloque-t-elle pas le ROP ?',
					'mode' => 'choice',
					'choices' => array(
						'Parce qu\'NX ne s\'applique qu\'au noyau',
						'Parce que le ROP utilise desAES',
						'Parce que NX désactive le canari',
						'Parce qu\'on n\'exécute pas de code placé dans la pile : on saute vers du code déjà exécutable',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'NX interdit d\'exécuter la pile, pas d\'y mettre des adresses.',
					'explanation' => 'La pile ne contient que des <em>adresses</em> : le CPU saute vers du code located elsewhere (le code du programme), qui est exécutable. La pile reste une donnée.',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — la chaîne de gadgets',
			'content' => '<p>Dans <code>/home/ctf/pwn</code>, le TP « Return Oriented Programming » a laissé sa <em>chaîne de gadgets</em> annotée (l\'ordre des gadgets à empiler).</p><p><strong>Mission.</strong> Lis cette annotation et relève la <em>valeur du nombre de gadgets</em> dans la chaîne (champ <code>chain_length</code>).</p>',
			'questions' => array(
				array(
					'question' => 'Releve le nombre de gadgets (chain_length) de la chaine indiquee dans le TP ROP.',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-u12.txt',
					'xp' => 30,
					'hint' => 'Le TP ROP est dans <code>/home/ctf/pwn</code> : plusieurs fichiers, lis celui qui parle de la chaîne.',
					'explanation' => 'Compter les gadgets d\'une chaîne, c\'et understand qu\'une exploitation est un <em>assemblage</em> : chaque pièce a un rôle, l\'ordre compte.',
				),
			),
		),
		array(
			'type' => 'exam',
			'format' => 'qcm',
			'title' => 'Task 4 : Examen de fin de room',
			'content' => '<p>Quatre questions chronométrées. 60 % suffisent pour valider.</p>',
			'time_limit' => 300,
			'pass_score' => 60,
			'questions' => array(
				array(
					'question' => 'Quel gadget est typiquement utilisé pour placer un argument dans le premier registre ?',
					'mode' => 'choice',
					'choices' => array(
						'<code>syscall ; ret</code>',
						'<code>leave ; ret</code>',
						'<code>nop ; ret</code>',
						'<code>pop rdi ; ret</code>',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'Il faut « dépiler » une valeur dans un registre.',
					'explanation' => 'En ABI System V, les arguments passent dans <code>rdi</code>, <code>rsi</code>... Un gadget <code>pop rdi ; ret</code> y place la valeur empilée, et le <code>ret</code> suivant enchaîne le prochain gadget.',
				),
				array(
					'question' => 'Que se passe-t-il si la chaîne de gadgets est dans le mauvais ordre ?',
					'mode' => 'choice',
					'choices' => array(
						'Les valeurs arrivent dans les mauvais registres et l\'appel système échoue',
						'Le programme fait la même chose, l\'ordre n\'a pas d\'importance',
						'Le programme démarre plus lentement',
						'Le canari est désactivé',
					),
					'correct' => 0,
					'xp' => 10,
					'hint' => 'Chaque gadget agit sur l\'état du CPU au moment où il s\'exécute.',
					'explanation' => 'Le ROP est un programme écrit en codes de retour : l\'ordre des pièces détermine ce qui se passe. Un mauvais ordre donne des registres mal remplis, donc un appel qui échoue.',
				),
				array(
					'question' => 'Pourquoi le ROP est-il considéré comme une technique plus avancée que le débordement « classique » ?',
					'mode' => 'choice',
					'choices' => array(
						'Parce qu\'il demande plus d\'octets',
						'Parce qu\'il faut comprendre la conventions d\'appel, trouver les gadgets et construire une chaîne cohérente',
						'Parce qu\'il ne fonctionne qu\'avec de vieux noyaux',
						'Parce qu\'il n\'a besoin d\'aucune adresse',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'On ne dépose plus de code : on construit un en assembleur de gadgets.',
					'explanation' => 'Il faut connaître l\'ABI (quels registres, dans quel ordre), trouver des gadgets compatibles et ordonner la chaîne. C\'est de la vraie construction, pas de la brute force.',
				),
				array(
					'question' => 'Un programme sans aucun gadget utile (pas de <code>pop rdi</code>, pas de <code>syscall</code> utile) est-il exploitable par ROP ?',
					'mode' => 'choice',
					'choices' => array(
						'Oui, toujours',
						'Oui, en écrivant le shellcode dans le tas',
						'Non, pas par cette technique : il faut chercher une autre primitive',
						'Oui, si le programme est en 64 bits',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'La chaîne a besoin de pièces ; sans pièces, pas de chaîne.',
					'explanation' => 'Le ROP dépend des gadgets présents. Si le binaire n\'en offre pas, l\'attaquant change de technique (ret2libc, JOP, ou autre primitive).',
				),
			),
		),
	),
	'i18n' => array(
		'ar' => array(
			'title' => 'ROP: هجوم بلا شيفرة شل',
			'excerpt' => 'عندما لا يمكن تنفيذ المكدس، نُرجع البرنامج إلى نفسه.',
			'tasks' => array(
				array( 'title' => 'المهمة 1: الدرس — العودة كتعليمة' ),
				array( 'title' => 'المهمة 2: تدريب' ),
				array( 'title' => 'المهمة 3: المهمة — سلسلة القطع' ),
				array( 'title' => 'المهمة 4: امتحان نهاية الغرفة' ),
			),
		),
		'en' => array(
			'title' => 'ROP: building an attack without shellcode',
			'excerpt' => 'When the stack cannot execute, you bounce the program off itself.',
			'tasks' => array(
				array( 'title' => 'Task 1: Lesson - the return as an instruction' ),
