array(
	'title' => 'Vulnérabilité de format string : printf qui parle trop',
	'excerpt' => 'Un %s de trop, et le programme va chercher l\'information à ta place.',
	'content' => 'L\'introduction aux format string exploits de pwn.college : lire la mémoire, puis écrire dedans.',
	'difficulty' => 'difficile',
	'duration' => 40,
	'xp_bonus' => 55,
	'track' => 'universites',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'single',
		'image' => 'securalabs/univ-01:1.0',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://127.0.0.1:8080',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings' ),
	),
	'video' => array(
		'id' => 'vc_9Ujkpy7I',
		'title' => 'Format String Exploits - Introduction',
		'channel' => 'pwn.college',
		'institution' => 'pwn.college (Arizona State University)',
		'license' => 'Reutilisation non commerciale autorisee, avec attribution (pwn.college)',
		'duration' => '9:47',
		'note' => 'Vidéo de l\'université (pwn.college). Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — le format qui devient une adresse',
			'content' => '<p>La famille <code>printf</code> estodr flexible : <code>printf("%s", s)</code> affiche une chaîne, mais <code>printf(s)</code> l\'interprète comme un <em>format</em>. Si l\'utilisateur contrôle <code>s</code>, il contrôle ce que le programme va <strong>lire en mémoire</strong> — et parfois ce qu\'il va <strong>écrire</strong>.</p><p>La mécanique est simple à comprendre :</p><ul><li><code>%x</code> affiche un mot hexadécimal lu dans la pile (ou dans les registres) ;</li><li><code>%s</code> affiche la chaîne pointée par la valeur lue ;</li><li><code>%n</code> <strong>écrit</strong> le nombre de caractères affichés à l\'adresse lue ;</li><li><code>%n</code> est le plus dangereux : c\'est une <strong>écriture arbitraire</strong>.</li></ul><p>Deux conséquences :</p><ol><li><strong>Fuite d\'information</strong> : en empilant des <code>%p</code>, on fait cracher au programme les adresses qu\'il a en mémoire. Avec ASLR, c\'est de l\'or : on récupère la base du programme ou l\'adresse d\'une pile libc.</li><li><strong>Écriture arbitraire</strong> : avec <code>%n</code>, on écrit une valeur choisie à l\'adresse choisie. On peut alors écraser une entrée de table de sauts, un pointeur de fonction, ou le GOT (table des fonctions déjà résolues) pour prendre le contrôle du flot.</li></ol><p>La parade est simple et connue : <strong>toujours passer le format comme constante</strong>, jamais comme donnée. <code>printf("%s", user_input)</code> et non <code>printf(user_input)</code>. Le compilateur peut même vous aider : <code>gcc -Wformat-security</code> avertit.</p><p><strong>À retenir :</strong> une format string, c\'est un contrôleur de lecture <em>et</em> d\'écriture fourni à l\'utilisateur. Le corriger coûte une ligne de code ; l\'exploiter demande des heures.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions : lire, écrire, et réparer.</p>',
