		'note' => 'Vidéo de l\'université (CYBER.ORG). Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — le mot de passe qui résiste',
			'content' => '<p>Un mot de passe, c\'est une <em>clé</em>. On ne la choisit pas pour qu\'elle soit aesthetics : on la choisit pour qu\'elle résiste. Trois règles, et le reste est de la décoration.</p><ol><li><strong>La longueur d\'abord.</strong> Chaque caractère ajouté multiplie le nombre de combinaisons. Quatre mots sans lien (« pêche verteocode porte bicycle ») se retiennent <em>et</em> résistent, alors qu\'un mot compliqué se devine par dictionnaire en quelques secondes.</li><li><strong>L\'unicité ensuite.</strong> Un mot de passe réutilisé sur deux sites, c\'est deux sites qui peuvent être cambriolés avec le même passe. Le mot de passe du forum de jeux est devenu la clé de ta boîte mail.</li><li><strong>Le rangement, enfin.</strong> Un gestionnaire de mots de passe (celui du navigateur, ou un logiciel dédié) crée un mot de passe différent pour chaque site et ne les retient qu\'à ta place. Il ne faut plus se souvenir : il faut savoir où c\'est.</li></ol><p>Et les réflexes d\'hygiène autour : ne jamais réutiliser le mot de passe d\'un autre compte, changer dès qu\'on a un doute (un service qui a été cambriolé), et vérifier qu\'un mot de passe n\'a pas fuité (un service qui le demande à l\'inscription est déjà en train de le stocker).</p><p><strong>À retenir :</strong> la longueur est une technique, pas un caprice. Un mot de passe long, unique et rangé est imbattable — même s\'il a l\'air moins « fort ».</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions : le bon réflexe et le piège classique.</p>',
			'questions' => array(
				array(
					'question' => 'Quel mot de passe résiste le mieux à une attaque par dictionnaire ?',
					'mode' => 'choice',
					'choices' => array(
