					),
					'correct' => 0,
					'xp' => 10,
					'hint' => 'Une attaque par dictionnaire teste des mots, pas des phrases.',
					'explanation' => 'Les outils de cassage testent des millions de mots et de variantes. Quatre mots sans lien ne figurent dans aucun dictionnaire : c\'est la longueur et le hasard qui protègent, pas les symboles.',
