			'title' => 'Task 3 : La mission — la fiche des mots de passe',
			'content' => '<p>Dans la salle des cours, l\'atelier CYBER.ORG a laissé une <em>fiche d\'hygiène</em> (<code>/srv/cours/cyber/password-sheet.txt</code>) : la longueur bat la complexité, et la fiche propose un <em>sac de mots</em> pour composer une phrase de passe.</p><p><strong>Mission.</strong> Les mots du sac sont dans <code>/srv/cours/cyber/mots.txt</code>, un par ligne. La valeur du drapeau est le <em>premier de ces mots dans l\'ordre alphabétique</em> : c\'est celui que l\'atelier donne en exemple.</p>',
			'questions' => array(
