					'explanation' => 'Une phrase de passe se compose de mots sans rapport entre eux : « pluie-ululement-vache » se retient et résiste mieux qu\'un mot court semé de symboles. Trier une liste de mots, c\'est aussi la première étape pour repérer les doublons d\'un dictionnaire.',
