array(
	'title' => 'Hameçonnage : lire un message avant de cliquer',
	'excerpt' => 'Le hameçonnage ne se-rate pas : il se repère. Quatre signaux à vérifier en trente secondes.',
	'content' => 'Le réflexe CYBER.ORG : ralentir, lire l\'adresse, vérifier qui envoie, se méfier de l\'urgence.',
	'difficulty' => 'facile',
	'duration' => 25,
	'xp_bonus' => 35,
	'track' => 'universites',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'single',
		'image' => 'securalabs/univ-01:1.0',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://127.0.0.1:8080',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings' ),
	),
	'video' => array(
		'id' => '08oJtFFH6a0',
		'title' => 'Phishing - Cyber Safety Series',
		'channel' => 'CYBER. ORG',
		'institution' => 'CYBER.ORG',
		'license' => 'Usage pedagogique avec attribution (CYBER.ORG)',
		'duration' => '2:28',
		'note' => 'Vidéo de l\'université (CYBER.ORG). Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — les quatre signaux',
			'content' => '<p>Un message qui veut te faire agir vite est suspect par nature. L\'hameçonnage (phishing) est une <em>usine à mensonges</em> : un faux message qui imite une banque, une école, un service de livraison, pour obtenir un mot de passe, un code ou un clic qui installe un logiciel.</p><p>Quatre signaux, à vérifier dans cet ordre :</p><ol><li><strong>L\'adresse réelle</strong> : on regarde le domaine, pas le nom affiché. « support@banque-secure.com » n\'est pas une banque. Les-domaines trompeur (remplacement de lettre, sous-domaine inattendu) sont le indice numéro un.</li><li><strong>L\'urgence</strong> : « votre compte sera bloqué dans 24 h », « votre colis est en attente ». L\'urgence est un levier : elle court-circuite ta prudence. Une vraie banque ne menace pas par SMS.</li><li><strong>La demande inhabituelle</strong> : demander un mot de passe, un code de validation ou un paiement par message, c\'est <em>toujours</em> suspect. Les codes de validation, par définition, ne se partagent jamais.</li><li><strong>L\'incohérence</strong> : un ton inhabituel, une faute, un logo mal copié, un lien qui ne va pas là où il dit aller (survoler le lien avant de cliquer).</li></ol><p>La parade : <strong>ne jamais cliquer dans le message</strong>. Ouvrir le site en tapant l\'adresse soi-même, ou appeler le service par un numéro connu. Et si un message Creates de la panique, c\'est justement le moment de ralentir.</p><p><strong>À retenir :</strong> la technique des pirates, ce n\'est pas la technique : c\'est l\'urgence. Apprendre à la voir, c\'est savoir s\'arrêter.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions : reconnaître, et réagir.</p>',
			'questions' => array(
				array(
					'question' => 'Tu reçois « Votre colis est bloqué,_regularisez dans 2 h : http://livraison-colis-urgent.xyz/paiement ». Que faut-il faire en premier ?',
					'mode' => 'choice',
					'choices' => array(
						'Cliquer et payer les frais, le colis est peut-être vraiment bloqué',
						'Ne pas cliquer : ouvrir le site du transporteur en tapant son adresse, ou appeler le numéro officiel',
						'Transmettre le message à un ami pour demander son avis',
						'Répondre au message pour demander de combien il s\'agit',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'Le message ne doit jamais être le chemin pour aller sur le site.',
					'explanation' => 'La règle : on ne passe jamais par le lien reçu. On va sur le site par l\'adresse connue, ou on appelle le numéro officiel. Le lien, lui, peut mener n\'importe où — et l\'urgence est exactement le piège.',
				),
				array(
					'question' => 'Un site te demande un code de validation par SMS pour « confirmer » une connexion. Que faut-il en penser ?',
					'mode' => 'choice',
