	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — ce que tu publies, ce qu\'on publie sur toi',
			'content' => '<p>Publier en ligne, ce n\'est pas juste « mettre une photo ». Trois choses se jouent en même temps :</p><ul><li><strong>Ce que tu publies</strong> : photos, localisation, école, opinions. Ce qui est publié reste publié : un contenu peut être recopié, cité, ou ressorti des années plus tard.</li><li><strong>Ce que les autres publient sur toi</strong> : une photo de toi à une fête, une mention, un like sur une photo de groupe. Les autres ont le droit de poster, même ce que tu aurais garder pour toi.</li><li><strong>Ce que la plateforme en sait</strong> : ce que tu regardes, tes recherches, ta position, le temps passé. Les réglages de confidentialité existent, mais ils changent souvent : il faut les vérifier, pas supposer.</li></ul><p>Les réflexes utiles :</p><ol><li><strong>Réfléchir avant de publier</strong> : la règle des trois questions — est-ce que ça me concerne encore dans cinq ans ? est-ce que j\'aimerais que ma famille le voie ? est-ce que je peux l\'expliquer à un recruteur ?</li><li><strong>Vérifier les réglages</strong> : liste d\'amis, localisation, qui peut commenter, qui peut t\'ajouter. Les valeurs par défaut sont souvent larges.</li><li><strong>Limiter les traces</strong> : ne pas publier d\'adresse complète, pas de photo de badge, pas d\'info sur tes horaires.</li><li><strong>Signaler et partir</strong> : face à du harcèlement ou à une menace, on bloque, on signale, on garde des preuves, et on ne répond pas.</li></ol><p><strong>À retenir :</strong> sur un réseau social, tu ne publies pas seulement : tu rends public ce que les autres disent de toi. C\'est le sens de « visibility ».</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions : ce que tu publies, ce que tu exposes.</p>',
			'questions' => array(
				array(
					'question' => 'Un ami poste une photo de toi à une soirée sur un compte public. Que peux-tu faire ?',
					'mode' => 'choice',
					'choices' => array(
						'Rien : c\'est sa photo, il a le droit',
						'Publier la même photo en retour',
						'Demander la suppression, signaler le contenu si besoin, garder une copie de la preuve, et ajuster tes réglages de confidentialité',
						'Changer de mot de passe',
