					'correct' => 2,
					'xp' => 10,
					'hint' => 'C\'est ton image : tu as des leviers, et il faut les utiliser vite.',
					'explanation' => 'Tu peux demander la suppression (souvent elle suffit), signaler, et surtout garder une preuve (capture, lien, date) : c\'est ce qui sert si la situation s\'aggrave. En parallèle, on durcit ses réglages pour la prochaine fois.',
				),
				array(
					'question' => 'Pourquoi publier la localisation en direct pendant un voyage est-il déconseillé ?',
					'mode' => 'choice',
					'choices' => array(
						'Parce que cela consomme des données',
						'Parce que les téléphones s\'éteignent',
