					'xp' => 10,
					'hint' => 'Qui lit l\'information ?',
					'explanation' => 'La localisation en direct est une invitation. Les cambriolages et les embuscades commencent souvent par une information de ce type. Le bon réflexe : publier après, pas pendant.',
