			'title' => 'Task 3 : La mission — la charte de publication',
			'content' => '<p>Dans la salle des cours, la <em>charte de publication</em> des réseaux sociaux fixe les règles de l\'atelier. Le laboratoire applique un délai de relecture avant publication, et les délais constatés sur trois publications sont dans <code>/srv/cours/cyber/delais.txt</code>, en heures.</p><p><strong>Mission.</strong> La valeur du drapeau est la <em>somme des trois délais</em>, en heures : c\'est le temps total de relecture que l\'équipe a consommé.</p>',
			'questions' => array(
