array(
	'title' => 'Hygiène numérique : le deuxième facteur',
	'excerpt' => 'Un code à six chiffres ne protège que si personne ne peut le deviner : d\'où les listas de codes.',
	'content' => 'La vidéo CYBER.ORG sur l\'authentification multifacteur : ce que le second facteur protège vraiment.',
	'difficulty' => 'facile',
	'duration' => 25,
	'xp_bonus' => 35,
	'track' => 'universites',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'single',
		'image' => 'securalabs/univ-01:1.0',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://127.0.0.1:8080',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings' ),
	),
	'video' => array(
		'id' => '-mdIH67HKqk',
		'title' => 'Multi-factor Authentication - Cyber Safety Series',
		'channel' => 'CYBER. ORG',
		'institution' => 'CYBER.ORG',
		'license' => 'Usage pedagogique avec attribution (CYBER.ORG)',
		'duration' => '2:48',
		'note' => 'Vidéo de l\'université (CYBER.ORG). Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — les trois facteurs',
			'content' => '<p>Un facteur d\'authentification, c\'est une catégorie de preuve. Il y en a trois :</p><ul><li><strong>Ce que tu sais</strong> : un mot de passe, un PIN, la date de naissance.</li><li><strong>Ce que tu as</strong> : ton téléphone, une clé USB, une carte à puce.</li><li><strong>Ce que tu es</strong> : ton empreinte, ton visage, ton iris.</li></ul><p>L\'authentification multifacteur combine <strong>deux catégories différentes</strong>. C\'est ce qui compte : un second facteur qui est aussi « ce que tu sais » (un PIN) ne protège pas d\'un vol de mot de passe.</p><p>Et là, la nuance qui fait la différence entre « activé » et « utile » :</p><ul><li><strong>Code reçu par SMS</strong> : utile contre le vol de mot de passe, mais le numéro peut être réattribué ou intercepté (SIM swap). Correct, mais perfectible.</li><li><strong>Application d\'authentification</strong> (code à 6 chiffres qui change toutes les 30 secondes) : bien meilleur : rien ne transitera par le réseau.</li><li><strong>Clé physique (FIDO2 / clé de sécurité)</strong> : la plus résistante, parce qu\'elle exige la présence physique de la clé et qu\'elle ne se laisse pas deviner.</li></ul><p>Et les deux règles qui restent : <strong>ne jamais partager un code</strong> (personne légitime ne te le demandera, jamais), et <strong>préférer l\'application à un SMS</strong> quand le service le propose.</p><p><strong>À retenir :</strong> le deuxième facteur ne sert que s\'il vient d\'une autre catégorie que le mot de passe. Sinon, il ne bloque que les approximations grossières.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions : le bon facteur, et le mauvais réflexe.</p>',
			'questions' => array(
				array(
					'question' => 'Quel est le meilleur second facteur pour un compte de messagerie ?',
					'mode' => 'choice',
					'choices' => array(
						'Un code reçu par SMS',
						'Une question secrète : « quel était le nom de ton premier animal ? »',
						'Un mot de passe plus long',
						'Une application d\'authentification (code qui change) ou une clé de sécurité physique',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'Ce qu\'on cherche, c\'est un facteur qui ne transite pas par le réseau.',
					'explanation' => 'L\'application d\'authentification et la clé FIDO2 sont les plus solides. Le SMS est correct maisinterceptable. La question secrète est presque toujours devinable ou trouvable en ligne : c\'est « ce que tu sais », donc pas un second facteur.',
				),
				array(
					'question' => 'Un service te demande le code reçu par SMS « pour vérifier que c\'est bien toi ». Que faut-il en faire ?',
					'mode' => 'choice',
					'choices' => array(
						'Ne jamais le donner : un code reçu par SMS ne se communique à personne, et un service légitime n\'a pas besoin de le demander',
						'Le donner : c\'est la procédure',
						'Le donner seulement s\'il s\'agit de ta banque',
						'L\'envoyer par mail à ton compte de secours',
					),
					'correct' => 0,
					'xp' => 10,
					'hint' => 'Qui te demande de confirmer quelque chose ?',
					'explanation' => 'Le code prouve que c\'est TOI qui es connecté. Le donner à quelqu\'un, c\'est lui donner l\'accès. Un service légitime ne demande jamais ce code : il l\'a déjà, ou il t\'en envoie un nouveau.',
				),
			),
		),
		array(
			'type' => 'test',
