	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — une liste de risques, pas un catalogue',
			'content' => '<p>Le <strong>Top 10 OWASP</strong> est la liste des dix risques les plus présents dans les applications web. Elle est révisée tous les ans, parce que le web change : les failles de navigateur ont reculé, les failles de logique et de configuration sont remontées.</p><p>Deux idées à retenir de la vidéo de la fondation :</p><ul><li><strong>Une liste, c\'est un outil de priorisation.</strong> On ne peut pas corriger les dix mille problèmes d\'une application : on regarde d\'abord ce qui est dans la liste, parce que ce sont les risques que l\'on retrouve partout.</li><li><strong>Les risques sont des catégories, pas des failles précises.</strong> « Injection » n\'est pas « mon application est injectable » : c\'est « mon application reçoit des données et les concatène dans une requête ». La catégorie sert à <?>penser, la faille exacte se trouve par le test.</li></ul><p>Et la notion de <strong>surface d\'attaque</strong> : tout ce que l\'application accepte du monde extérieur (formulaires, URL, en-têtes, fichiers, websockets). Plus la surface est large, plus il y a de chemins à tester. Réduire la surface (supprimer une vieille API, un port inutile, un module oublié) est une défense <em>gratuite</em>, avant même d\'écrire une ligne de code de sécurité.</p><p>Les entrées de la version 2021 qu\'on rencontre le plus : contrôle d\'accès cassé, erreur cryptographique, injection, conception non sécurisée, misconfiguration, composants vulnérables, authentification défaillante, défaut d\'intégrité des données, journalisation et surveillance insuffisantes, et gestion d\'erreurs excessive.</p><p><strong>À retenir :</strong> la liste ne sert pas à dire « on est protégé parce qu\'on a lu le Top 10 ». Elle sert à dire « voici par où commencer, et voici les questions à se poser ».</p><p><strong>Aller plus loin, gratuitement :</strong> la <a href="https://portswigger.net/web-security" target="_blank" rel="noopener">Web Security Academy de PortSwigger</a> propose plusieurs centaines de labs web sur exactement ces failles (injection SQL, XSS, contournement des droits, requêtes forgées…). Les labs sont gratuits et se pratiquent sur des applications volontairement vulnérables. Nous n\'en reprenons pas le contenu : nous y renvoyons, en nommant la source et son adresse.</p>',
			'questions' => array(),
