			'content' => '<p>Dans la salle des cours, l\'équipe a laissé son <em>classement des risques</em> (<code>/srv/cours/owasp/risques.txt</code>) : les cinq risques du Top 10 rencontrés dans son propre code, un par ligne.</p><p><strong>Mission.</strong> On ne corrige pas tout en même temps : on commence par celui qui vient en premier dans l\'ordre alphabétique. La valeur du drapeau est ce <em>premier risque</em>, tel qu\'il est écrit.</p>',
