array(
	'title' => 'Valider les entrées : le premier remède anti-injection',
	'excerpt' => 'Ne jamais faire confiance à ce qui vient du monde extérieur : la règle qui élimine la moitié des failles web.',
	'content' => 'La démonstration de Cristi Vlad sur l\'OWASP Juice Shop : tester la validation des entrées sur une vraie application vulnérable.',
	'difficulty' => 'moyen',
	'duration' => 35,
	'xp_bonus' => 45,
	'track' => 'universites',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'single',
		'image' => 'securalabs/univ-01:1.0',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://127.0.0.1:8080',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings' ),
	),
	'video' => array(
		'id' => 'EA8-GuMZykg',
		'title' => 'Real World Application Security - How to Test with OWASP [Input Validation]',
		'channel' => 'Cristi Vlad',
		'institution' => 'OWASP (chapitre Presedint)',
		'license' => 'Usage pedagogique avec attribution (Cristi Vlad)',
		'duration' => '12:08',
		'note' => 'Vidéo de Cristi Vlad (chapitre OWASP). Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — valider, escaping, requêtes préparées',
			'content' => '<p>Trois notions à ne pas confondre, et qui règlent l\'essentiel des injections :</p><ul><li><strong>La validation</strong> : vérifier que la donnée est du bon <em>type</em> et dans le bon <em>domaine</em>. « 42 » pour un âge, « AAA-BBB-123 » pour un code postal, « 10/03/2026 » pour une date. Si la donnée n\'est pas conforme, on la refuse — et c\'est fini.</li><li><strong>L\'échappement</strong> (ou <em>encoding</em>) : transformer les caractères spéciaux pour qu\'ils soient du texte et non du code. C\'est indispensable pour tout ce qui est affiché dans du HTML, du JavaScript, une URL ou une commande shell.</li><li><strong>Les requêtes préparées</strong> (<em>prepared statements</em>) : c\'est LA parade pour les injections SQL. La requête et les données sont envoyées séparément : la base ne peut pas confondre « la donnée » et « la commande ».</li></ul><p>Et ce qui ne marche pas : <strong>échapper à la main</strong>, filtrer une liste de mots interdits (<code>OR</code>, <code>DROP</code>...), ou compter sur le front-end. Un filtre de mots se contourne en écrivant autrement ; une validation uniquement dans le navigateur est contournée par une simple requête HTTP.</p><p>La règle d\'or, celle que la vidéo répète : <strong>« Ne jamais construire une commande ou une requête avec des données venues d\'ailleurs. »</strong> Si on ne peut pas utiliser de requête préparée, on échappe avec la fonction de la bibliothèque, jamais à la main.</p><p>Et la même logique s\'applique au-delà du SQL : une commande shell construite par concaténation est une injection de commande ; un lien construit avec une donnée non échappée est une injection XSS.</p><p><strong>À retenir :</strong> la validation, c\'est le bouclier ; l\'échappement, c\'est l\'encre ; la requête préparée, c\'est le blindage. On utilise les trois.</p><p><strong>Aller plus loin, gratuitement :</strong> la <a href="https://portswigger.net/web-security" target="_blank" rel="noopener">Web Security Academy de PortSwigger</a> propose plusieurs centaines de labs web sur exactement ces failles (injection SQL, XSS, contournement des droits, requêtes forgées…). Les labs sont gratuits et se pratiquent sur des applications volontairement vulnérables. Nous n\'en reprenons pas le contenu : nous y renvoyons, en nommant la source et son adresse.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions : la bonne parade, et le faux remède.</p>',
			'questions' => array(
				array(
					'question' => 'Quel est l\'avantage décisif d\'une requête préparée face à l\'injection SQL ?',
					'mode' => 'choice',
					'choices' => array(
						'Elle est plus rapide à exécuter',
						'La requête et les données sont envoyées séparément : la base ne peut plus interpréter la donnée comme du code',
