						'Elle chiffre la base de données',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'Pense à la frontière entre « commande » et « donnée ».',
					'explanation' => 'La requête préparée fait respected la frontière : le paramètre est une valeur, jamais une portion de SQL. C\'est la parade structurelle, là où l\'échappement reste une technique.',
				),
				array(
					'question' => 'Un développeur filtre les mots « SELECT », « DROP » et « UNION » dans les champs de formulaire. Quel est le problème ?',
					'mode' => 'choice',
					'choices' => array(
						'Aucun : c\'est une filtre efficace',
						'C\'est trop lent pour un site moderne',
						'La liste est infinie : on peut écrire la même chose autrement (commentaires, encodages, autres mots-clés)',
						'Le navigateur refuse ce filtrage',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'On peut écrire « SELECT » autrement.',
					'explanation' => 'Le filtrage par mots-clés est un jeu sans fin : variantes d\'écriture, autres commandes, techniques d\'évasion. La parade sérieuse est structurelle (requête préparée) ou contextuelle (échappement adapté au contexte de sortie).',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — la règle de validation',
