array(
	'title' => 'Journaux et audit : la trace qui vaut de l\'or',
	'excerpt' => 'Sans trace, pas d\'enquête : ce qu\'il faut logger, et ce qu\'il ne faut surtout pas logger.',
	'content' => 'La vidéo OWASP sur les défaillances de journalisation (A09:2021) : ce qu\'un journal doit permettre de reconstituer.',
	'difficulty' => 'moyen',
	'duration' => 30,
	'xp_bonus' => 40,
	'track' => 'universites',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'single',
		'image' => 'securalabs/univ-01:1.0',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://127.0.0.1:8080',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings' ),
	),
	'video' => array(
		'id' => 'ODpooAzCuwM',
		'title' => 'Security Logging and Monitoring Failures Explained | OWASP A09:2021',
		'channel' => 'AppSecDojo',
		'institution' => 'OWASP Top 10 (A09:2021)',
		'license' => 'Usage pedagogique avec attribution (AppSecDojo)',
		'duration' => '1:01',
		'note' => 'Vidéo de la communauté OWASP. Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — journaliser, alerter, protéger',
			'content' => '<p>Un journal, c\'est la mémoire du système. Sans lui, un incident est un roman : « ça a dû arriver à quelqu\'un, mais je ne sais ni quand ni comment ». Avec lui, on peut reconstituer la chronologie et répondre aux trois questions que pose toujours un jury après un incident : <strong>que s\'est-il passé, est-ce que ça s\'est reproduit, est-ce qu\'on a été prévenu</strong>.</p><p>Ce qu\'un journal doit contenir :</p><ul><li><strong>Qui</strong> : le compte concerné (et l\'adresse IP si elle est fiable).</li><li><strong>Quoi</strong> : l\'action tentée (connexion, changement de mot de passe, export, refus).</li><li><strong>Quand</strong> : l\'horodatage précis, avec fuseau.</li><li><strong>Résultat</strong> : succès ou échec, et le code d\'erreur.</li><li><strong>Origine</strong> : l\'IP, le user-agent, l\'identifiant de session.</li></ul><p>Et les <strong>deux pièges</strong> que la vidéo souligne :</p><ol><li><strong>Logger trop</strong> : journaliser les mots de passe, les numéros de carte, les jetons de session ou les données personnelles. Un journal devient alors une base de données sensible — et il faut le protéger comme telle (accès restreint, durée de conservation limitée).</li><li><strong>Logger trop peu</strong> : ne pas journaliser les échecs d\'authentification, les changements de privilèges, les accès aux données sensibles. Sans ces traces, on ne voit pas la préparation d\'une attaque.</li></ol><p>Et la partie qu\'on oublie souvent : <strong>alerter</strong>. Un journal que personne ne surveille n\'a servi à rien. Une règle simple : un journal doit déclencher une alerte quand il contient un motif rare et grave (rafale d\'échecs, changement de permissions, export massif).</p><p><strong>À retenir :</strong> le journal n\'est pas une trace technique, c\'est une pièce d\'enquête. Il doit être horodaté, protégé, et lu.</p><p><strong>Aller plus loin, gratuitement :</strong> la <a href="https://portswigger.net/web-security" target="_blank" rel="noopener">Web Security Academy de PortSwigger</a> propose plusieurs centaines de labs web sur exactement ces failles (injection SQL, XSS, contournement des droits, requêtes forgées…). Les labs sont gratuits et se pratiquent sur des applications volontairement vulnérables. Nous n\'en reprenons pas le contenu : nous y renvoyons, en nommant la source et son adresse.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions : quoi logger, quoi ne pas logger.</p>',
			'questions' => array(
				array(
					'question' => 'Quel élément ne doit JAMAIS être écrit dans un journal ?',
					'mode' => 'choice',
					'choices' => array(
						'L\'horodatage',
						'L\'adresse IP de origem',
						'Le mot de passe ou le jeton de session en clair',
						'Le résultat de l\'opération',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'Le journal doit permettre de reconstituer une action, pas de rejouer une authentification.',
					'explanation' => 'Un journal qui contient un mot de passe ou un jeton est une bombe : quiconque y accède prend le compte. On journalise l\'événement (« authentification réussie pour l\'utilisateur X »), jamais le secret.',
				),
				array(
					'question' => 'Pourquoi est-il important de journaliser les échecs d\'authentification ?',
					'mode' => 'choice',
					'choices' => array(
						'Pour pouvoir bloquer définitivement les comptes',
						'Parce que le serveur l\'exige',
						'Pour compter les utilisateurs actifs',
						'Parce qu\'une rafale d\'échecs est un signal d\'attaque : c\'est souvent la première alerte',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'Ce qui n\'a pas réussi laisse une trace, et cette trace arrive souvent en premier.',
					'explanation' => 'L\'échec est le signal le plus précoce d\'une attaque par force brute. S\'il n\'est pas journalisé (ou pas surveillé), on l\'apprend en même temps que la compromission : trop tard.',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — le plan de journalisation',
			'content' => '<p>Dans la salle des cours, l\'équipe a laissé son <em>plan de journalisation</em> et la trace que le service a produite (<code>/srv/cours/owasp/trace.txt</code>) : chaque ligne est un événement.</p><p><strong>Mission.</strong> La valeur du drapeau est le <em>nombre d\'événements</em> de cette trace. Trois questions en découlent : combien de connexions refusées, combien de changements de configuration, et qui a fait quoi.</p>',
			'questions' => array(
				array(
					'question' => 'Combien d\'evenements contient la trace du service (trace.txt) ?',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-u20.txt',
					'xp' => 30,
					'hint' => '<code>wc -l < /srv/cours/owasp/trace.txt</code>. Regarde aussi la trace : <code>grep refusee</code>, <code>grep configuration</code>.',
					'explanation' => 'Un journal ne vaut que si on sait le lire : combien de lignes, combien de refus, quelle séquence précède l\'incident. Compter les événements est le premier pas ; la question suivante, c\'est « combien sont anormaux ».',
				),
			),
		),
		array(
			'type' => 'exam',
			'format' => 'qcm',
			'title' => 'Task 4 : Examen de fin de room',
			'content' => '<p>Quatre questions chronométrées. 60 % suffisent pour valider.</p>',
			'time_limit' => 300,
			'pass_score' => 60,
			'questions' => array(
				array(
