					'explanation' => 'Un mot de passe dans un journal survit au changement de mot de passe : le journal est souvent conservé des mois, lu par des équipes nombreuses. La bonne pratique est de journaliser l\'événement, jamais le secret.',
				),
				array(
					'question' => 'Un journal est bien alimenté, mais personne ne le lit. Quel est le défaut ?',
					'mode' => 'choice',
					'choices' => array(
						'Aucun : l\'écriture suffit',
						'La surveillance fait partie du dispositif : sans alerte, le journal ne sert qu\'après l\'incident',
