					'explanation' => 'Un journal surveillé permet d\'agir pendant l\'attaque ; un journal non surveillé sert d\'archive après coup. D\'où l\'importance des règles d\'alerte sur les événements rares et graves.',
				),
				array(
					'question' => 'Quel événement est le plus utile à journaliser pour détecter une compromission en cours ?',
					'mode' => 'choice',
					'choices' => array(
						'L\'arrivée d\'un visiteur sur la page d\'accueil',
