					'hint' => 'Cherche l\'événement rare et grave, pas le bruit quotidien.',
					'explanation' => 'Les changements de privilèges (un compte qui devient administrateur, un accès à un fichier sensible) sont rares et graves : ce sont eux qui méritent une alerte. Le reste est du bruit.',
