array(
	'title' => 'Comment marche un ordinateur : de la donnée au programme',
	'excerpt' => 'Des bits aux instructions : ce qui se passe vraiment entre le clavier et le résultat affiché.',
	'content' => 'La première leçon de Stanford (CS105, "Introduction to Computers") : comment une machine transforme des données en programme.',
	'difficulty' => 'facile',
	'duration' => 30,
	'xp_bonus' => 40,
	'track' => 'universites',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'single',
		'image' => 'securalabs/univ-01:1.0',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://127.0.0.1:8080',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings' ),
	),
	'video' => array(
		'id' => 'KkMDCCdjyW8',
		'title' => 'Lecture 1 | Programming Methodology (Stanford)',
		'channel' => 'Stanford',
		'institution' => 'Stanford - Engineering Everywhere (SEE)',
		'license' => 'CC BY-NC-SA 4.0 - Stanford Engineering Everywhere',
		'duration' => '49:47',
		'note' => 'Cours vidéo de l\'université (Stanford). Cette room est notre pratique du même cours.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — de la donnée au programme',
			'content' => '<p>Un ordinateur ne « comprend » rien : il exécute des instructions, dans l\'ordre, a une vitesse folle et sans jamais se lasser. Tout le reste est de l\'organisation.</p><p>Le trajet d\'un programme, en quatre couches :</p><ol><li><strong>Les données</strong> : tout est nombre binaire. Un caractère est un nombre, une image est un tableau de nombres, un son est une suite d\'échantillons. La seule unité de la machine, c\'est le bit.</li><li><strong>La mémoire</strong> : une longue suite d\'octets, numérotés. Chaque case porte une <em>adresse</em>. Une variable, c\'est un nom donné à une adresse : le programme manipule des noms, la machine manipule des adresses.</li><li><strong>L\'instruction</strong> : une opération élémentaire (charger, ajouter, stocker, sauter). Un programme, c\'est une longue suite de ces instructions.</li><li><strong>Le cycle</strong> : le processeur prend l\'instruction à l\'adresse pointée par le compteur, l\'exécute, passe à la suivante. Rien d\'autre. C\'est là que se glissent les notions de sécurité : qui contrôle le compteur de programme, et que se passe-t-il quand on lui fait sauter ailleurs ?</li></ol><p>La notion de <strong>langage de haut niveau</strong> vient ensuite : on écrit <code>x = 5 + 3</code>, le compilateur traduit en instructions, l\'assembleur les traduit en codes machines, et le processeur les exécute. Chaque couche ajoute du confort… et parfois des erreurs (les famous <em>buffer overflow</em> viennent de ce que la couche C ne protège pas la mémoire).</p><p><strong>À retenir :</strong> l\'ordinateur est une machine à instructions qui manipule des adresses. Toute la sécurité repose sur le contrôle de ces trois choses : les données, les adresses, et le compteur de programme.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions : ce que la machine fait, et ce que le langage cache.</p>',
			'questions' => array(
				array(
					'question' => 'Que fait réellement un processeur ?',
					'mode' => 'choice',
					'choices' => array(
						'Il lit des instructions, les exécute une par une, et passe à la suivante',
						'Il comprend le programme et l\'exécute selon le sens',
						'Il compile le code source',
						'Il stocke les données sur le disque',
					),
					'correct' => 0,
					'xp' => 10,
					'hint' => 'Le processeur ne connaît ni le sens, ni les intentions : il suit un compteur.',
					'explanation' => 'Le processeur exécute un flux d\'instructions piloté par un compteur de programme. Toute la sécurité des systèmes repose sur le contrôle de ce compteur — d\'où l\'intérêt des defenses comme le canari ou le NX.',
				),
				array(
					'question' => 'Pourquoi dit-on que le langage C est « proche de la machine » ?',
					'mode' => 'choice',
					'choices' => array(
						'Parce qu\'il est plus rapide que tous les autres langages',
						'Parce qu\'il laisse le programmeur gérer la mémoire : il n\'y a ni garbage collector ni vérification automatique des bornes',
						'Parce qu\'il a été écrit en assembleur',
						'Parce qu\'il n\'a pas de fonctions',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'Ce n\'est pas une question de vitesse, c\'est une question de garanties.',
					'explanation' => 'En C, la gestion de la mémoire est à la charge du programmeur : c\'est une puissance (performance, contrôle) et un risque (dépassements, use-after-free). C\'est exactement ce que les labs pwn.college exploitent.',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — le schéma de la machine',
