		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — ranger, chercher, séparer',
			'content' => '<p>Toute l\'informatique tient dans une phrase : <strong>ranger l\'information pour la retrouver</strong>. Le web, un jeu, un site de commerce : ce sont des données rangées et relues.</p><p>Les paliers du rangement :</p><ul><li><strong>Le fichier</strong> : un bloc d\'octets nommé. Simple, mais pour trouver une information, il faut tout lire. C\'est le cas d\'un <em>log</em> : on le lit à la fin pour savoir ce qui s\'est passé.</li><li><strong>La table (base de données)</strong> : des lignes et des colonnes typées, avec des index. L\'index, c\'est le « sommaire » : il permet de trouver une ligne sans tout parcourir. C\'est un compromis : de la place en plus, du temps gagné.</li><li><strong>La requête</strong> : on ne lit plus les données, on pose une question. « Donne-moi les commandes du client X après le 3 mars ». C\'est le langage SQL, et c\'est aussi le point d\'entrée classique des injections.</li></ul><p>Et la notion de <strong>séparation des responsabilités</strong> : données, code applicatif, configuration, journaux. Les mélanger est la cause numéro un des fuites : un mot de passe écrit dans le code, une clé de chiffrement dans un fichier servi au public, un journal dans le même répertoire que les données.</p><p>Pour la sécurité, deux règles tirees de cette organisation :</p><ol><li><strong>Un accès, un besoin</strong> : le service web lit les données, il ne modifie pas le schéma. Un compte de service distinct pour la lecture, un autre pour l\'écriture : c\'est la version « données » de la séparation des privilèges.</li><li><strong>Le secret ne vit pas à côté des données</strong> : il vit dans un endroit protégé, avec un accès mesuré et une durée de vie limitée.</li></ol><p><strong>À retenir :</strong> la sécurité des données commence par leur rangement. Qui peut lire, qui peut écrire, et où sont les secrets : trois questions à se poser avant tout.</p>',
			'questions' => array(),
