					'explanation' => 'Ranger, en sécurité, ce n\'est pas trier : c\'est séparer ce qui a le droit de se côtoyer. Un fichier <code>.env</code> dans le dossier servi par le web est une fuite qui n\'a pas l\'air d\'en être une.',
