		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'curl', 'python3', 'nc' ),
	),
	'video' => array(
		'id' => 'nq-Igdk0o7s',
		'title' => 'The How and Why of the OWASP Top Ten 2021 - Brian Glas',
		'channel' => 'OWASP Foundation',
		'institution' => 'OWASP Foundation',
		'license' => 'CC BY-SA 4.0 - OWASP',
		'duration' => '49:37',
		'note' => 'Le Top 10 de l\'OWASP : la liste de référence que la boutique Juice Shop rejoue, un point à la fois.',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — une application web, et ce qu\'elle révèle',
			'content' => '<p>Tu vas travailler sur <strong>OWASP Juice Shop</strong> : une application de commerce en ligne volontairement vulnérable, écrite par l\'OWASP et utilisée partout dans le monde pour apprendre à tester une application web. Elle tourne ici <em>seule</em> dans un réseau fermé : personne dehors ne peut la voir.</p><p>Trois choses à comprendre avant de commencer :</p><ul><li><strong>Une application web, c\'est un serveur qui répond à des requêtes.</strong> Ton terminal parle au serveur (port 3000) comme un navigateur le ferait. Ce que tu tapes dans le formulaire de connexion part dans une requête HTTP.</li><li><strong>Une injection SQL, c\'est une requête qui contient du code.</strong> Si le serveur colle naivement ce que tu écris dans sa requête SQL, tu ne « falsifies » pas la donnée : tu <em>écris</em> une autre requête. Là où il attend un identifiant, tu peux faire lire toute la table des comptes.</li><li><strong>Une preuve vaut mieux qu\'une intuition.</strong> L\'application tient un tableau de défis. Quand tu en résous un, elle affiche un <em>code de drapeau</em> : c\'est ce code qu\'on va te demander.</li></ul><p><strong>À retenir :</strong> on n\'attaque pas une application « pour le plaisir ». On teste une <em>idée</em> — « et si ce champ n\'était pas validé ? » — et on note ce que la machine répond. C\'est exactement le travail d\'un testeur.</p><p><strong>Aller plus loin, gratuitement :</strong> la <a href="https://portswigger.net/web-security" target="_blank" rel="noopener">Web Security Academy de PortSwigger</a> propose plusieurs centaines de labs web sur exactement ces failles (injection SQL, XSS, contournement des droits, requêtes forgées…). Les labs sont gratuits et se pratiquent sur des applications volontairement vulnérables. Nous n\'en reprenons pas le contenu : nous y renvoyons, en nommant la source et son adresse.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions avant de toucher à la boutique.</p>',
			'questions' => array(
				array(
					'question' => 'Que se passe-t-il si le serveur utilise directement ce que tu écris dans un champ pour construire sa requête SQL ?',
					'mode' => 'choice',
					'choices' => array(
						'Tu peux modifier le sens de la requête : c\'est une injection SQL',
						'La requête est refusée, la base est protégée',
						'Le serveur affiche un message d\'erreur plus détaillé',
