					'hint' => 'Une injection qui marche dans un formulaire marche dans les autres.',
					'explanation' => 'Le champ « e-mail » de la connexion est famously injectable : une condition toujours vraie transforme la requête en « renvoie le premier compte », et ce compte est un administrateur. La zone d\'administration devient alors accessible.',
