			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — le code du défi « Login Admin »',
			'content' => '<p>La boutique est déployée dans ton lab : l\'application répond sur <code>http://juice:3000</code>. Ton terminal est à côté.</p><p><strong>Mission.</strong> Connecte-toi en administrateur sans connaître le mot de passe (c\'est une injection SQL), puis relève le <strong>code de drapeau</strong> que l\'application affiche quand le défi « Login Admin » est résolu. C\'est une suite de 40 caractères hexadécimaux : recopie-la exactement.</p>',
			'questions' => array(
				array(
					'question' => 'Recopie le code de drapeau affiché par l\'application quand le défi « Login Admin » est résolu.',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-login-admin.txt',
					'xp' => 40,
					'hint' => 'Dans le formulaire de connexion, un e-mail comme <code>\' OR 1=1--</code> transforme la condition de la requête. Le code apparaît dans la notification de l\'application, en bas à droite.',
					'explanation' => 'Le code affiché par Juice Shop est une empreinte calculée à partir du nom du défi et d\'une clé que nous fixons. Ce n\'est pas une invention : c\'est la preuve que le défi « Login Admin » est réellement résolu dans l\'application. Le serveur de la plateforme compare ta réponse au code qu\'il garde de son côté.',
				),
			),
		),
		array(
			'type' => 'exam',
			'format' => 'qcm',
			'title' => 'Task 4 : Examen de fin de room',
			'content' => '<p>Trois questions sur ce que tu viens de faire. 60 % suffisent pour valider.</p>',
			'time_limit' => 300,
			'pass_score' => 60,
			'questions' => array(
				array(
					'question' => 'Pourquoi tester une application dans un réseau fermé est-il une bonne pratique ?',
					'mode' => 'choice',
					'choices' => array(
						'C\'est plus rapide, donc moins cher',
						'On évite d\'atteindre un système réel qui n\'a rien demandé',
						'Le réseau fermé rend les failles invisibles',
						'C\'est la seule façon de voir le code source',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'Qui a autorisé le test ?',
					'explanation' => 'Tester une application sans autorisation, c\'est une intrusion, même si c\'est « pour apprendre ». Le lab est isolé, hors d\'Internet, et personne d\'autre n\'est concerné : c\'est la condition pour apprendre tranquillement.',
				),
				array(
					'question' => 'Une injection SQL qui renvoie « trop de résultats » indique quoi ?',
					'mode' => 'choice',
					'choices' => array(
						'Que la base est trop grosse',
						'Que le compte est banni',
						'Que la requête a été exécutée mais renvoie plusieurs lignes : l\'injection a fonctionné',
						'Que le mot de passe est trop long',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'Relis la phrase : le nombre de résultats est-il normal ?',
					'explanation' => 'Quand l\'injection fonctionne, la condition est vraie pour plusieurs comptes : le serveur en renvoie plusieurs. C\'est le symptôme typique, et c\'est ce qui permet de passer d\'un compte normal à un compte administrateur.',
				),
				array(
					'question' => 'Qu\'est-ce qui distingue un test d\'une attaque ?',
					'mode' => 'choice',
					'choices' => array(
						'La vitesse',
						'Le nombre de machines touchées',
						'L\'utilisation d\'un outil',
