					'correct' => 3,
					'xp' => 10,
					'hint' => 'Le même geste peut être un test ou une attaque : qu\'est-ce qui change ?',
					'explanation' => 'Un test part d\'une autorisation et s\'arrête à la démonstration. Une attaque n\'a ni l\'un ni l\'autre. C\'est pourquoi la plateforme insiste : on travaille sur une application qui nous attend, isolée, et la preuve se lit dans la machine.',
				),
