array(
	'title' => 'La zone administrateur : ce qu\'un administrateur voit',
	'excerpt' => 'Une fois dans l\'espace administrateur, on découvre ce que la boutique cache : les commandes des clients, les signalements, les produits.',
	'content' => 'Deuxième room Juice Shop : après avoir obtenu un accès administrateur, on regarde ce que ce compte donne — et on comprend pourquoi les comptes powerful sont la cible numéro un.',
	'difficulty' => 'moyen',
	'duration' => 40,
	'xp_bonus' => 60,
	'track' => 'avance',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'compose',
		'image' => 'securalabs/univ-01:1.0',
		'compose' => 'juice-shop/docker-compose.yml',
		'service' => 'attacker',
		'project' => 'seca_juice',
		'flag_service' => 'flags',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://juice:3000',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'curl', 'python3', 'nc' ),
	),
	'video' => array(
		'id' => 'EA8-GuMZykg',
		'title' => 'Real World Application Security - How to Test with OWASP',
		'channel' => 'OWASP Foundation',
		'institution' => 'OWASP Foundation',
		'license' => 'CC BY-SA 4.0 - OWASP',
		'duration' => '12:08',
		'note' => 'Comment tester une application web en conditions réelles (OWASP).',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — le compte qui peut tout',
			'content' => '<p>Un compte administrateur, dans une application, ce n\'est pas « un compte plus gros ». C\'est un compte qui peut <strong>voir et modifier les données des autres</strong>.</p><p>Dans Juice Shop, l\'espace administration montre :</p><ul><li>le <strong>catalogue des produits</strong> (et le moyen de le modifier) ;</li><li>la <strong>liste des commandes</strong> des clients (donc leurs adresses) ;</li><li>les <strong>signalements</strong> des utilisateurs ;</li><li>la <strong>configuration</strong> de l\'application.</li></ul><p>Deux idées à retenir pour la suite :</p><ol><li><strong>Le vrai danger n\'est pas le compte, c\'est ce qu\'il permet.</strong> Un compte admin sur une boutique, c\'est l\'accès aux données de tous les clients.</li><li><strong>Chaque écran d\'administration est un nouvel endroit à tester.</strong> On y trouve souvent des fonctions que personne n\'utilise, donc personne ne teste : c\'est exactement là que se cachent les failles (injection, XSS stockée, téléversement de fichier sans contrôle).</li></ol><p><strong>À retenir :</strong> un test ne s\'arrête pas à « je suis entré ». Il va jusqu\'à « voici ce que cet accès permet vraiment de faire ».</p><p><strong>Aller plus loin, gratuitement :</strong> la <a href="https://portswigger.net/web-security" target="_blank" rel="noopener">Web Security Academy de PortSwigger</a> propose plusieurs centaines de labs web sur exactement ces failles (injection SQL, XSS, contournement des droits, requêtes forgées…). Les labs sont gratuits et se pratiquent sur des applications volontairement vulnérables. Nous n\'en reprenons pas le contenu : nous y renvoyons, en nommant la source et son adresse.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions sur les comptes et les droits.</p>',
			'questions' => array(
				array(
					'question' => 'Pourquoi dit-on souvent que « l\'administrateur n\'est pas un superutilisateur » ?',
					'mode' => 'choice',
					'choices' => array(
						'Parce qu\'un administrateur a moins de droits qu\'un utilisateur',
						'Parce qu\'un administrateur a des droits différents, qui ne sont pas « plus de droits » mais « d\'autres droits »',
						'Parce qu\'un administrateur est un role a part, pas un superutilisateur',
						'Parce que le mot « administrateur » est un mot-clé ancien',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'Il ne s\'agit pas de quantité, mais de nature.',
					'explanation' => 'Un compte administrateur n\'est pas « root » : il est administrateur *de l\'application*. Dans Juice Shop, il ne peut pas chiffrer ni supprimer le serveur : il peut modifier le catalogue et lire les commandes. La security est une affaire de contexte, pas de volume de droits.',
				),
				array(
					'question' => 'Un endpoint d\'administration oublié (non lié dans le menu) est-il dangereux ?',
					'mode' => 'choice',
					'choices' => array(
						'Non, si personne ne le connaît',
						'Non, le serveur le désactive tout seul',
						'Oui : l\'absence de lien ne protège pas, et l\'URL se devine ou se trouve',
						'Seulement s\'il accepte des fichiers',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'Une porte sans poignée n\'est pas une porte fermée.',
					'explanation' => 'C\'est une erreur classique : un endpoint d\'administration retiré de l\'interface mais toujours actif. Un routeur le discovery vite, et il reste actif pendant des mois. La règle : ce qui n\'est plus utilisé doit être désactivé, pas caché.',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — le code du défi « Admin Section »',
			'content' => '<p>Toujours dans la boutique (toujours déployée dans ton lab). Cette fois, l\'objectif n\'est plus de se connecter, mais d\'<strong>atteindre la zone d\'administration</strong> et de la regarder.</p><p><strong>Mission.</strong> Une fois dans l\'espace administration, relève le <strong>code de drapeau</strong> que l\'application affiche quand le défi « Admin Section » est résolu (40 caractères hexadécimaux).</p>',
			'questions' => array(
				array(
					'question' => 'Recopie le code de drapeau affiché par l\'application quand le défi « Admin Section » est résolu.',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-admin-section.txt',
					'xp' => 40,
					'hint' => 'Une fois connecté en administrateur, la zone d\'administration devient accessible. Le code arrive dans la notification de l\'application.',
					'explanation' => 'Atteindre l\'espace administration, c\'est un défaut d\'autorisation : l\'application a laissé passer une session qui ne devrait pas donner accès à ces écrans. Le code affiché est la preuve que l\'écran a réellement été atteint.',
				),
			),
		),
		array(
			'type' => 'exam',
			'format' => 'qcm',
			'title' => 'Task 4 : Examen de fin de room',
			'content' => '<p>Trois questions sur les droits et les écrans d\'administration. 60 % suffisent.</p>',
			'time_limit' => 300,
			'pass_score' => 60,
			'questions' => array(
				array(
					'question' => 'Que faut-il tester en priorité dans un espace d\'administration ?',
					'mode' => 'choice',
					'choices' => array(
						'Le logo et les couleurs',
						'Le nombre d\'utilisateurs connectés',
						'Les fonctions qui existent mais ne sont pas utilisées au quotidien',
						'La vitesse d\'affichage',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'C\'est là que personne ne va regarder.',
					'explanation' => 'Les fonctions rarement utilisées échappent aux tests : personne ne les utilise, donc personne ne les surveille. C\'est là que se logent les vulnérabilités les plus graves, parce que personne ne les répare.',
				),
				array(
					'question' => 'Le « moindre privilège », pour un compte d\'administration, veut dire :',
					'mode' => 'choice',
					'choices' => array(
						'Donner tous les droits pour aller vite',
						'Donner les droits au premier qui demande',
						'Supprimer tous les comptes',
						'Ne donner que les droits qui servent à la tâche, et retirer le reste',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'Moins, mais juste ce qu\'il faut.',
					'explanation' => 'Un compte qui peut tout peut être volé puis utilisé pour tout. Le moindre privilège ne coûte presque rien à mettre en place et évite qu\'un vol de compte devienne une catastrophe.',
				),
				array(
					'question' => 'Pourquoi la boutique est-elle un cas d\'école ?',
					'mode' => 'choice',
					'choices' => array(
						'Parce qu\'elle réunit dans une même application toutes les failles classiques du web',
						'Parce qu\'elle vend des produits interestingly',
						'Parce que c\'est la plus grande boutique du monde',
						'Parce que son code est public',
					),
					'correct' => 0,
					'xp' => 10,
					'hint' => 'Regarde la liste des défis : elle ressemble à l\'OWASP Top 10.',
					'explanation' => 'Juice Shop réunit dans une seule application des vulnérabilités de toutes catégories : injection, XSS, mots de passe faibles, erreurs de configuration. C\'est pourquoi elle est l\'outil d\'apprentissage le plus utilisé au monde.',
				),
			),
		),
	),
	'i18n' => array(
		'ar' => array(
			'title' => 'منطقة المسؤول: ما يراه المسؤول',
			'excerpt' => 'بعد الدخول إلى مساحة المسؤول، نكتشف ما تخفيه المتجر: طلبات الزبائن، الشكاوى، المنتجات.',
			'tasks' => array(
				array( 'title' => 'المهمة 1: الدرس — الحساب الذي يملك كل شيء' ),
				array( 'title' => 'المهمة 2: تدريب' ),
				array( 'title' => 'المهمة 3: المهمة — رمز التحدي «Admin Section»' ),
				array( 'title' => 'المهمة 4: امتحان نهاية الغرفة' ),
			),
		),
		'en' => array(
			'title' => 'The administrator area: what an administrator sees',
			'excerpt' => 'Once inside the admin area, we discover what the shop hides: customer orders, reviews, products.',
			'tasks' => array(
				array( 'title' => 'Task 1: Lesson - the account that can do everything' ),
				array( 'title' => 'Task 2: Practice' ),
				array( 'title' => 'Task 3: Mission - the code of the "Admin Section" challenge' ),
				array( 'title' => 'Task 4: End-of-room exam' ),
			),
