array(
	'title' => 'Ceinture blanche : lire, chercher, comprendre',
	'excerpt' => 'Quatre défis pour apprendre à regarder un fichier et à y trouver ce qu\'on cherche.',
	'content' => 'Ceinture blanche du dojo Secura : quatre défis, quatre preuves à relever dans la machine.',
	'difficulty' => 'moyen',
	'duration' => 30,
	'xp_bonus' => 50,
	'track' => 'avance',
	'lab' => array(
		'enabled' => 1,
		'driver' => 'auto',
		'mode' => 'single',
		'image' => 'securalabs/dojo-01:1.0',
		'network' => 'seca_lab',
		'command' => 'sleep infinity',
		'workdir' => '/home/ctf',
		'target' => 'http://127.0.0.1:8080',
		'ttl' => 3600,
		'allow' => array( 'ls', 'cat', 'grep', 'head', 'tail', 'wc', 'find', 'file', 'stat', 'strings', 'sha256sum' ),
	),
	'video' => array(
		'id' => 'A5CnZGst5u4',
		'title' => 'pwn.college - Exploitation Scenarios - Introduction',
		'channel' => 'pwn.college (Arizona State University)',
		'institution' => 'pwn.college - Arizona State University',
		'license' => 'Reutilisation non commerciale autorisee, avec attribution (pwn.college)',
		'duration' => '7:21',
		'note' => 'Présentation de la méthode des scénarios d\'exploitation (pwn.college).',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — la ceinture blanche',
			'content' => '<p>La première ceinture est celle de l\'observation. Pas de technique compliquée : juste apprendre à regarder un fichier, à le parcourir, et à y repérer une valeur.</p><p>Ce que tu vas apprendre :</p><ul><li><code>cat</code> — tout le fichier, d\'un coup ;</li><li><code>ls -a</code> — y compris ce qui est <em>caché</em> (le point devant) ;</li><li><code>grep</code> — trouver une ligne qui contient un mot ;</li><li><code>head</code> et <code>tail</code> — le début et la fin.</li></ul><p><strong>À retenir :</strong> avant de demander « comment je pirate ? », demande « qu\'y a-t-il exactement dans ce fichier ? ». La plupart du temps, la réponse est déjà là, en clair.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions sur les outils de cette ceinture.</p>',
			'questions' => array(
				array(
					'question' => 'Quelle commande affiche le contenu complet d\'un fichier ?',
					'mode' => 'choice',
					'choices' => array(
						'ls',
						'cd',
						'cat',
						'ps',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'Une commande pour lire, une pour lister.',
					'explanation' => '<code>cat</code> affiche le contenu. <code>ls</code> liste des fichiers, <code>cd</code> change de répertoire, <code>ps</code> liste les processus. Confusion classique : l\'outil du jour n\'est pas toujours l\'outil du moment.',
				),
				array(
					'question' => 'Pourquoi utiliser `ls -a` plutôt que `ls` ?',
					'mode' => 'choice',
					'choices' => array(
						'Pour avoir la taille des fichiers',
						'Pour trier par date',
						'Pour lister les dossiers seulement',
						'Pour voir aussi les fichiers cachés (ceux qui commencent par un point)',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'Qu\'est-ce qui peut manquer à `ls` ?',
					'explanation' => 'Les fichiers cachés commencent par un point. <code>ls</code> les saute ; <code>ls -a</code> les montre. C\'est là que se cachent les fichiers de configuration « secrets » — et parfois les drapeaux.',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — les quatre défis de la ceinture',
			'content' => '<p>Le dojo est déployé dans ta machine. Les quatre défis de la ceinture <strong>blanche</strong> se trouvent dans :</p><ul><li><strong>Le premier fichier</strong> — Le fichier de compte rendu du premier défi. (<code>/srv/dojo/1-blanche/01-premier-fichier.txt</code>)</li>
<li><strong>Le dossier caché</strong> — Un fichier commence par un point : les outils simples ne le voient pas. (<code>/srv/dojo/1-blanche/02-dossier-cache.txt</code>)</li>
<li><strong>Le mot dans le texte</strong> — Une ligne contient un mot précis : il faut la retrouver. (<code>/srv/dojo/1-blanche/03-mot-dans-le-texte.txt</code>)</li>
<li><strong>Les première et dernière lignes</strong> — Le début et la fin du fichier, c\'est souvent là que se trouve l\'information. (<code>/srv/dojo/1-blanche/04-extremites.txt</code>)</li></ul><p><strong>Mission.</strong> Ouvre chaque document, relève la valeur de compte rendu (la ligne <code>... = FLAG=SECURA{...}</code>), et réponds aux quatre questions. Le serveur compare chaque réponse au drapeau qu\'il garde en root.</p>',
			'questions' => array(
				array(
					'question' => 'Défi « Le premier fichier » (d01) : rapporte la valeur affichée par ton terminal.',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-d01.txt',
					'xp' => 20,
					'hint' => 'Le dossier de la ceinture blanche est dans <code>/srv/dojo</code>, mais le drapeau n\'y est PAS écrit : le document te dit quoi faire, et le terminal produit le résultat.',
					'explanation' => 'Tu viens de faire le geste du défi, pas de recopier une valeur. Le serveur lit le drapeau dans la machine, en root : il n\'est écrit nulle part dans les documents du dojo.',
				),
				array(
					'question' => 'Défi « Le dossier caché » (d02) : rapporte la valeur affichée par ton terminal.',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-d02.txt',
					'xp' => 20,
					'hint' => 'Le dossier de la ceinture blanche est dans <code>/srv/dojo</code>, mais le drapeau n\'y est PAS écrit : le document te dit quoi faire, et le terminal produit le résultat.',
					'explanation' => 'Tu viens de faire le geste du défi, pas de recopier une valeur. Le serveur lit le drapeau dans la machine, en root : il n\'est écrit nulle part dans les documents du dojo.',
				),
				array(
					'question' => 'Défi « Le mot dans le texte » (d03) : rapporte la valeur affichée par ton terminal.',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-d03.txt',
					'xp' => 20,
					'hint' => 'Le dossier de la ceinture blanche est dans <code>/srv/dojo</code>, mais le drapeau n\'y est PAS écrit : le document te dit quoi faire, et le terminal produit le résultat.',
					'explanation' => 'Tu viens de faire le geste du défi, pas de recopier une valeur. Le serveur lit le drapeau dans la machine, en root : il n\'est écrit nulle part dans les documents du dojo.',
				),
				array(
					'question' => 'Défi « Les première et dernière lignes » (d04) : rapporte la valeur affichée par ton terminal.',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-d04.txt',
					'xp' => 20,
					'hint' => 'Le dossier de la ceinture blanche est dans <code>/srv/dojo</code>, mais le drapeau n\'y est PAS écrit : le document te dit quoi faire, et le terminal produit le résultat.',
					'explanation' => 'Tu viens de faire le geste du défi, pas de recopier une valeur. Le serveur lit le drapeau dans la machine, en root : il n\'est écrit nulle part dans les documents du dojo.',
				),
			),
