	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — la ceinture jaune',
			'content' => '<p>La ceinture jaune, c\'est le moment où l\'outil simple ne suffit plus. Le fichier est là, mais quelque chose te bloque : des <strong>permissions</strong>, un <strong>propriétaire</strong> différent du tien, un contenu qu\'on ne voit qu\'en partie.</p><p>Ce que tu vas apprendre :</p><ul><li><code>ls -l</code> — les droits, le propriétaire, le groupe, la taille ;</li><li><code>stat</code> — les détails d\'un fichier (type, taille, permissions) ;</li><li><code>grep -n</code> — le <em>numéro</em> de la ligne qui contient le mot ;</li><li><code>wc</code> — compter lignes, mots ou octets.</li></ul><p><strong>À retenir :</strong> un fichier que tu ne peux pas lire n\'est pas forcément absent. Il est peut-être protégé : et là, la bonne question n\'est pas « comment le lire ? » mais « <em>qui</em> le lit, et pourquoi lui ? ».</p>',
			'questions' => array(),
