						'Le fichier appartient au groupe root',
						'Le fichier est un dossier',
						'Le propriétaire peut lire, écrire et exécuter ; les autres peuvent lire et exécuter',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'Trois groupes de trois lettres : propriétaire, groupe, autres.',
					'explanation' => 'Le premier trio est le propriétaire, le deuxième le groupe, le troisième les autres. <code>rwx</code> = lire, écrire, exécuter. <code>-rwxr-xr-x</code> : le propriétaire a tous les droits, le groupe et les autres seulement lire et exécuter.',
				),
				array(
					'question' => 'Que fait `grep -n` en plus de `grep` ?',
					'mode' => 'choice',
					'choices' => array(
