			'title' => 'Task 3 : La mission — les quatre défis de la ceinture',
			'content' => '<p>Le dojo est déployé dans ta machine. Les quatre défis de la ceinture <strong>jaune</strong> se trouvent dans :</p><ul><li><strong>Le fichier protégé</strong> — Les permissions d\'un fichier se lisent d\'un coup avec `ls -l`. (<code>/srv/dojo/2-jaune/05-fichier-protege.txt</code>)</li>
<li><strong>Le dossier du vrai propriétaire</strong> — Le propriétaire d\'un fichier n\'est pas forcément toi. (<code>/srv/dojo/2-jaune/06-proprietaire.txt</code>)</li>
<li><strong>La ligne cachée</strong> — Une ligne cachée au milieu : `grep -n` donne son numéro. (<code>/srv/dojo/2-jaune/07-ligne-cachee.txt</code>)</li>
<li><strong>Le compte des caractères</strong> — Compter ce qu\'il y a dans un fichier, c\'est parfois la réponse. (<code>/srv/dojo/2-jaune/08-taille.txt</code>)</li></ul><p><strong>Mission.</strong> Ouvre chaque document, relève la valeur de compte rendu (la ligne <code>... = FLAG=SECURA{...}</code>), et réponds aux quatre questions. Le serveur compare chaque réponse au drapeau qu\'il garde en root.</p>',
