			'title' => 'Task 1 : Leçon — la ceinture verte',
			'content' => '<p>La ceinture verte change de support : on ne lit plus des textes, on regarde des <strong>binaires</strong> — des programmes compilés.</p><p>Ce que tu vas apprendre :</p><ul><li><code>file</code> — ce qu\'est vraiment ce fichier (exécutable, archive, image) ;</li><li><code>strings</code> — les bouts de texte cachés dans le binaire ;</li><li><code>stat</code> — la taille exacte, un indice qui saute aux yeux ;</li><li><code>grep</code> — retrouver une adresse, un message d\'erreur, un mot de passe.</li></ul><p><strong>À retenir :</strong> un binaire ne cache presque rien, il <em>montre</em> mal. Les chaînes de caractères restent dans le fichier : le mot de passe, l\'URL, le message d\'erreur qui trahit une bibliothèque. C\'est le principe même du cours 6.858 : « le programme ne dit pas ce qu\'il fait, mais il en montre les morceaux ».</p>',
