			'title' => 'Task 1 : Leçon — la ceinture noire',
			'content' => '<p>La ceinture noire, c\'est le monde des <strong>secrets qui ne sont pas en clair</strong> : des empreintes, des clés, des certificats. On ne les casse pas (on ne « craque » pas une clé) : on les <em>reconnaît</em>, on les lit, on vérifie.</p><p>Ce que tu vas apprendre :</p><ul><li><code>sha256sum</code> — calculer l\'empreinte d\'un fichier, et la comparer ;</li><li><code>grep</code> — repérer une clé ou un secret dans un fichier ;</li><li><code>openssl</code> — lire un certificat et comprendre ce qu\'il dit.</li></ul><p><strong>À retenir :</strong> une empreinte n\'est pas réversible : on ne « déchiffre » pas un hash, on le compare. Et comparer suppose qu\'on sache à quoi comparer : c\'est le rôle du serveur, dans notre plateforme.</p>',
