			'title' => 'Task 1 : Leçon — le dojo, comment on s\'entraîne',
			'content' => '<p>Un dojo, ce n\'est pas une liste de failles à enfoncer : c\'est une <strong>échelle</strong>. On monte ceinture par ceinture, et chaque ceinture fabrique une compétence.</p><p>La règle du dojo, en trois points :</p><ol><li><strong>Chercher la preuve, pas la faille.</strong> Un exercice te demande de relever une valeur précise. C\'est une preuve : on peut vérifier que tu as compris, pas deviner ce que l\'auteur avait dans la tête.</li><li><strong>Une seule commande à la fois.</strong> Au début, on lit. Ensuite seulement, on casse. Les ceintures hawks le font dans cet ordre, et ça marche.</li><li><strong>Le dojo n\'est pas un jeu solo.</strong> C\'est un entraînement : on peut recommencer, se tromper, et recommencer. L\'objectif n\'est pas la victoire, c\'est la competence.</li></ol><p><strong>À retenir :</strong> dans notre plateforme, chaque défi se valide avec un drapeau lu dans ta machine, par le serveur, en root. Tu ne peux pas tricher : tu peux seulement apprendre.</p>',
