					'xp' => 10,
					'hint' => 'Qu\'est-ce qui permet de dire « c\'est bon » ?',
					'explanation' => 'Une preuve se vérifie : le serveur lit la valeur dans la machine et la compare. Un exercice « à deviner » demande de reformuler ce que l\'auteur avait en tête : c\'est flou, et c\'est démotivant.',
				),
				array(
					'question' => 'Pourquoi commencer par lire avant de chercher à casser ?',
