	),
	'video' => array(
		'id' => 'UW13N0CV-4s',
		'title' => 'pwn.college - Talking Web - Introduction',
		'channel' => 'pwn.college (Arizona State University)',
		'institution' => 'pwn.college - Arizona State University',
		'license' => 'Reutilisation non commerciale autorisee, avec attribution (pwn.college)',
		'duration' => '9:43',
		'note' => 'Brief 2 : comment le web parle au serveur (pwn.college).',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — le web, comment on parle à un serveur',
			'content' => '<p>Un site web, c\'est un programme qui reçoit des textes et répond par des textes. Rien de plus. Le « web » n\'est pas une magie : c\'est un dialogue, et le dialogue est lisible.</p><p>La mécanique, en quatre temps :</p><ol><li>Le navigateur envoie une <strong>requête</strong> : une méthode (GET, POST), une adresse, des en-têtes, et parfois un corps.</li><li>Le serveur lit la requête, exécute son code, prépare une <strong>réponse</strong> : un code de statut (200, 404, 500…), des en-têtes, puis un corps.</li><li>Le corps peut être du HTML, du JSON, une image… ou du texte qui est ensuite exécuté par ton navigateur (JavaScript).</li><li>Chaque échange laisse une trace : dans les journaux du serveur, dans l\'historique du navigateur, dans la mémoire du serveur.</li></ol><p><strong>À retenir :</strong> tester une application web, c\'est d\'abord <em>lire les échanges</em>. Une injection SQL, une XSS, une fuite de secret : dans les trois cas, quelque chose que tu n\'aurais pas dû pouvoir écrire se retrouve dans une requête.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions pour vérifier que le brief est passé.</p>',
			'questions' => array(
				array(
					'question' => 'Que contient une requête HTTP GET ?',
					'mode' => 'choice',
					'choices' => array(
						'Une méthode, une adresse, des en-têtes et parfois un corps',
						'Seulement l\'adresse du site',
						'Uniquement des données chiffrées',
						'Un mot de passe et un nom d\'utilisateur',
					),
					'correct' => 0,
					'xp' => 10,
					'hint' => 'La requête, c\'est une envelope : qu\'y a-t-il dedans ?',
					'explanation' => 'Une requête HTTP, c\'est une méthode (GET, POST…), une adresse (la route et la requête), des en-têtes (qui parle, quel format, quel navigateur) et parfois un corps. Le POST envoie des données ; le GET les met dans l\'adresse.',
				),
				array(
					'question' => 'Que signifie le code de statut HTTP 404 ?',
					'mode' => 'choice',
					'choices' => array(
						'Le serveur a planté',
						'La ressource demandée n\'existe pas',
						'La requête a été refusée par le pare-feu',
