					),
					'correct' => 1,
					'xp' => 10,
					'hint' => '404 : laCombination de « pas trouvé » et de « 400-something ».',
					'explanation' => '404 = Not Found : le serveur répond, mais la page n\'existe pas. 500 = Internal Server Error : le serveur a planté en traitant la requête. 403 = Forbidden : le serveur a compris, mais refuse.',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — la preuve du brief',
			'content' => '<p>Le brief est écrit dans la machine du dojo, dans <code>/srv/briefs/02-talking-web.txt</code>.</p><p><strong>Mission.</strong> Ouvre ce document et relève la valeur qu\'il annonce. Le serveur la compare au drapeau qu\'il garde en root.</p>',
			'questions' => array(
				array(
					'question' => 'Relève la valeur du brief 2 (le web en clair).',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-b02.txt',
					'xp' => 20,
					'hint' => 'Les briefs sont dans <code>/srv/briefs</code>.',
					'explanation' => 'Même mécanique : une preuve lue dans la machine, comparée par le serveur en root.',
				),
			),
		),
		array(
			'type' => 'exam',
			'format' => 'qcm',
			'title' => 'Task 4 : Examen de fin de room',
			'content' => '<p>Deux questions sur ce brief. 60 % suffisent pour valider.</p>',
			'time_limit' => 300,
			'pass_score' => 60,
			'questions' => array(
				array(
					'question' => 'Une XSS (injection de script) consiste à…',
					'mode' => 'choice',
					'choices' => array(
						'Détruire la base de données',
						'Faire exécuter du code par le navigateur d\'une autre personne',
						'Inonder le serveur de requêtes',
						'Chiffrer les échanges',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'Le « X » de XSS, c\'est le script.',
					'explanation' => 'Une XSS, c\'est du code que tu places dans une donnée que l\'application réutilise sans l\'échapper, et qui s\'exécute chez celui qui affiche la page. Le risque : voler une session, ou agir avec les droits de la victime.',
				),
				array(
					'question' => 'Pourquoi lire les journaux du serveur est-il utile pour un test ?',
					'mode' => 'choice',
