					'xp' => 10,
					'hint' => 'Le journal est le récit de la requête.',
					'explanation' => 'Quand l\'application se comporte bizarrement, le journal montre la requête telle qu\'elle a été reçue. C\'est souvent là qu\'on voit la différence entre ce qu\'on a envoyé et ce que le serveur a compris.',
