			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — les scénarios d\'exploitation',
			'content' => '<p>Le mot « exploitation » fait peur, mais l\'idée est simple : <strong>faire faire à un programme quelque chose qu\'il ne prévoyait pas</strong>.</p><p>Tout scénario d\'exploitation a la même forme, en quatre temps :</p><ol><li><strong>Le déclencheur</strong> : l\'entrée que l programmes ne contrôle pas (une donnée envoyée par le réseau, un fichier, un paramètre).</li><li><strong>L\'écart</strong> : le programme fait une hypothèse qui n\'est pas garantie (« ce texte tient dans 32 octets », « ce nom est le bon »).</li><li><strong>La deviation</strong> : l\'entrée trigger déborde, se déforme, ou s\'exécute à la place de quelque chose d\'autre.</li><li><strong>L\'effet</strong> : ce que l\'attaquant obtient — lire un fichier, exécuter une commande, devenir root.</li></ol><p>Le bon réflexe : <strong>chercher l\'hypothèse fragile</strong>. Dans un programme, c\'est presque toujours une taille, un nombre, ou une permission : « et si la donnée était plus grande que prévu ? ».</p><p><strong>À retenir :</strong> une exploitation est toujours un <em>scénario</em>, donc elle s\'écrit. Si tu ne peux pas expliquer en trois phrases comment ça marche, tu n\'as probablement rien trouvé.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions pour vérifier que le brief est passé.</p>',
			'questions' => array(
				array(
					'question' => 'Dans un scénario d\'exploitation, qu\'est-ce que « l\'hypothèse fragile » ?',
					'mode' => 'choice',
					'choices' => array(
						'Le pare-feu de l\'entreprise',
						'Une belief du programme qui n\'est pas garantie, par exemple « cette donnée tient dans 32 octets »',
						'Le nom du programme',
						'La vitesse du réseau',
					),
					'correct' => 1,
					'xp' => 10,
					'hint' => 'Quelle phrase le programme suppose-t-il être vraie ?',
					'explanation' => 'L\'hypothèse fragile est l\'endroit où le programme fait confiance sans vérifier : une taille maximale, un identifiant, un droit d\'accès. C\'est là que se glisse l\'exploitation.',
				),
				array(
					'question' => 'Pourquoi « ça plante » n\'est pas une preuve d\'exploitation ?',
