	),
	'video' => array(
		'id' => 'IWbIZerH930',
		'title' => 'pwn college - Assembly Crash Course - Registers',
		'channel' => 'pwn.college (Arizona State University)',
		'institution' => 'pwn.college - Arizona State University',
		'license' => 'Reutilisation non commerciale autorisee, avec attribution (pwn.college)',
		'duration' => '13:47',
		'note' => 'Brief 4 : les registres du processeur (pwn.college).',
	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — les registres, le carnet du processeur',
			'content' => '<p>Un processeur ne lit pas les variables. Il lit des <strong>registres</strong> : des cases de mémoire Minuscules, très rapides, en nombre fixe (une douzaine sur x86-64).</p><p>Les plus utiles à connaître :</p><ul><li><code>rax</code>, <code>rbx</code>, <code>rcx</code>, <code>rdx</code> — usage général ;</li><li><code>rdi</code>, <code>rsi</code>, <code>rdx</code> — les trois premiers arguments (convention d\'appel System V, celle de Linux sur x86-64) ;</li><li><code>rsp</code> — le pointeur de pile : il dit où est le sommet de la pile ;</li><li><code>rbp</code> — le pointeur de base, la frame de la fonction en cours.</li></ul><p>Pourquoi ça compte pour la sécurité : au moment d\'un appel de fonction, l\'<strong>adresse de retour</strong> est empilée. Si un débordement atteint cette adresse, le programme sautera ailleurs : c\'est le principe de l\'attaque « smashing the stack ».</p><p><strong>À retenir :</strong> pour comprendre une exploitation, il faut savoir où sont les données <em>en ce moment</em>. Les registres, c\'est la réponse.</p>',
			'questions' => array(),
		),
		array(
			'type' => 'practice',
			'format' => 'qcm',
			'title' => 'Task 2 : Entraînement',
			'content' => '<p>Deux questions pour vérifier que le brief est passé.</p>',
			'questions' => array(
				array(
					'question' => 'Où se trouve l\'adresse de retour d\'une fonction ?',
					'mode' => 'choice',
					'choices' => array(
						'Dans un fichier du disque',
						'Dans un registre du processeur',
						'Sur la pile, au-dessus des variables locales',
						'Dans le journal du serveur',
					),
					'correct' => 2,
					'xp' => 10,
					'hint' => 'Au moment de l\'appel, qu\'est-ce qui est empilé ?',
					'explanation' => 'La convention d\'appel empile l\'adresse de retour, puis les variables locales. Un débordement de tampon écrit au-delà du tampon local et finit par atteindre cette adresse : d\'où la possibility de détourner l\'exécution.',
				),
				array(
					'question' => 'À quoi servent les registres comme `rdi`, `rsi`, `rdx` ?',
					'mode' => 'choice',
					'choices' => array(
						'À stocker des fichiers sur le disque',
						'À mesurer le temps d\'exécution',
						'À chiffrer la mémoire',
						'À passer les arguments d\'une fonction, selon la convention d\'appel',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'Comment un programme passe-t-il une valeur à une fonction ?',
					'explanation' => 'Sur x86-64 sous Linux, les trois premiers arguments passent dans rdi, rsi et rdx. Savoir cela permet de lire un désassemblage — et de comprendre une exploitation qui construit une chaîne « /bin/sh ».',
				),
			),
		),
		array(
			'type' => 'test',
			'format' => 'pratique',
			'title' => 'Task 3 : La mission — la preuve du brief',
			'content' => '<p>Le brief est écrit dans la machine du dojo, dans <code>/srv/briefs/04-registres.txt</code>.</p><p><strong>Mission.</strong> Ouvre ce document et relève la valeur qu\'il annonce. Le serveur la compare au drapeau qu\'il garde en root.</p>',
			'questions' => array(
				array(
					'question' => 'Relève la valeur du brief 4 (les registres).',
					'mode' => 'flag',
					'flag_path' => '/root/flags/flag-b04.txt',
					'xp' => 20,
					'hint' => 'Les briefs sont dans <code>/srv/briefs</code>.',
					'explanation' => 'Même mécanique : une preuve lue dans la machine, comparée par le serveur en root.',
				),
			),
		),
		array(
			'type' => 'exam',
			'format' => 'qcm',
			'title' => 'Task 4 : Examen de fin de room',
			'content' => '<p>Deux questions sur ce brief. 60 % suffisent pour valider.</p>',
			'time_limit' => 300,
			'pass_score' => 60,
			'questions' => array(
				array(
					'question' => 'Pourquoi une architecture sans registres serait-elle très lente ?',
					'mode' => 'choice',
					'choices' => array(
						'Parce que les registres coûtent cher en mémoire',
						'Parce que les registres ne sont pas fiables',
						'Parce que le code serait plus long',
						'Parce que le processeur est rapide, mais la mémoire ordinaire ne l\'est pas : les registres sont la mémoire la plus rapide qui existe',
					),
					'correct' => 3,
					'xp' => 10,
					'hint' => 'La vitesse vient de la distance, pas de la quantité.',
					'explanation' => 'Un registre est dans le processeur : un cycle. Une case de mémoire ordinaire demande des dizaines de cycles. Un programme qui travaille en mémoire est donc lent. Les registres sont la mémoire la plus rapide — et la plus petite.',
				),
				array(
					'question' => 'Le « canari » (stack protector), c\'est quoi ?',
					'mode' => 'choice',
					'choices' => array(
						'Une valeur placed entre le tampon et l\'adresse de retour, vérifiée avant le retour : si elle a changé, le programme s\'arrête',
						'Un mot de passe du système',
						'Un pare-feu du noyau',
						'Une copie de sauvegarde du tampon',
					),
					'correct' => 0,
					'xp' => 10,
					'hint' => 'Un gardien entre le tampon et l\'adresse de retour.',
					'explanation' => 'Le canari est une valeur aléatoire posée entre le tampon local et l\'adresse de retour. Avant de revenir, la fonction la compare : si elle a changé, c\'est qu\'un débordement a eu lieu, et le programme s\'interrompt. C\'est la défense vue en cours 6.858.',
