	),
	'tasks' => array(
		array(
			'type' => 'lesson',
			'format' => 'lecon',
			'title' => 'Task 1 : Leçon — ne pas se faire avoir',
			'content' => '<p>La vidéo de CYBER.ORG s\'adresse aux plus jeunes : c\'est le niveau où les pièges deviennent <em>quotidiens</em>. Trois réflexes :</p><ul><li><strong>L\'urgence est un outil.</strong> « Votre compte sera fermé dans deux heures », « il te reste 3 minutes » : l\'urgence empêche de réfléchir. Un vrai service ne menace pas de te punir.</li><li><strong>La faille de l\'émotion.</strong> La peur (« tu as été hacké »), la curiosité (« regarde cette photo »), la sympathie (« j\'ai besoin d\'aide ») : ce sont des portes d\'entrée, pas des sentiments.</li><li><strong>La règle de la pause.</strong> Quand un message te presse, on s\'arrête : on vérifie l\'adresse, on ouvre le site en tapant l\'adresse soi-même, on demande à un adulte.</li></ul><p><strong>À retenir :</strong> la technique la plus efficace contre l\'hameçonnage, ce n\'est pas de reconnaître un faux message : c\'est de savoir <em>où aller</em> sans passer par le message.</p>',
