					'correct' => 3,
					'xp' => 10,
					'hint' => 'Que fait l\'urgence sur toi ?',
					'explanation' => 'L\'urgence est une technique sociale : elle court-circuite la vérification. Si une menace te presse d\'agir tout de suite, c\'est précisément le moment de slows down — et de vérifier d\'où vient le message.',
				),
