			'content' => '<p>La démonstration de Joe Ma montre l\'ordre qu\'il faut respecter : <strong>d\'abord regarder, ensuite attaquer</strong>.</p><ol><li><strong>Regarde comme un utilisateur.</strong> Chaque bouton, chaque champ, chaque lien : à quoi ça sert, qui y accède, qu\'est-ce qui se passe quand ça échoue.</li><li><strong>Regarde les rôles.</strong> Un visiteur, un client, un administrateur : qu\'est-ce qu\'un visiteur ne devrait pas pouvoir voir ?</li><li><strong>Regarde les entrées.</strong> Chaque formulaire envoie quelque chose : que se passe-t-il si ce n\'est pas ce qu\'on attend ?</li><li><strong>Regarde ce qui est exposé.</strong> Les messages d\'erreur, les fichiers laissés sur le serveur, les pages oubliées.</li></ol><p><strong>À retenir :</strong> une application mal testée est d\'abord une application mal <em>comprise</em>. La faille est souvent dans une zone que personne n\'a prise la peine de regarder.</p>',
